[CmdletBinding()]
param(
    [Parameter(Position = 0)] [ValidateSet('init', 'install', 'validate', 'version', 'transition')] [string]$Command = 'validate',
    [string]$Target, [string]$ProjectName, [switch]$Force, [switch]$Template,
    [string]$To, [string]$Actor, [string]$Reference,
    [string]$ChangeRequest, [string]$BlockerCode, [string]$BlockerExplanation,
    [string[]]$BlockerReference = @()
)

$ErrorActionPreference = 'Stop'
$instanceRoot = [IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot))
$dependencyPath = Join-Path $instanceRoot 'vendor/YamlDotNet/18.1.0/YamlDotNet.dll'
$maxYamlBytes = 1048576
$maxYamlDepth = 64
$script:Warnings = [Collections.Generic.List[string]]::new()

function Fail([string]$Message) { throw $Message }
function FullPath([string]$Path) { [IO.Path]::GetFullPath($Path) }
function Normalize-Root([string]$Path) { (FullPath $Path).TrimEnd([char]'\', [char]'/' ) }
function Get-RelativePath([string]$Base,[string]$Path) {
    $method=[IO.Path].GetMethod('GetRelativePath',[type[]]@([string],[string]));if($null -ne $method){return [IO.Path]::GetRelativePath($Base,$Path)}
    $baseUri=[Uri]::new(([IO.Path]::GetFullPath((Join-Path $Base ''))));$pathUri=[Uri]::new(([IO.Path]::GetFullPath($Path)));return [Uri]::UnescapeDataString($baseUri.MakeRelativeUri($pathUri).ToString()).Replace('/','\')
}
function Get-Sha256Bytes([byte[]]$Bytes){$sha=[Security.Cryptography.SHA256]::Create();try{return $sha.ComputeHash($Bytes)}finally{$sha.Dispose()}}
function Get-Sha256Hex([byte[]]$Bytes){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Is-Map($Node) { $null -ne $Node -and $Node -is [YamlDotNet.RepresentationModel.YamlMappingNode] }
function Is-Seq($Node) { $null -ne $Node -and $Node -is [YamlDotNet.RepresentationModel.YamlSequenceNode] }
function Is-Scalar($Node) { $null -ne $Node -and $Node -is [YamlDotNet.RepresentationModel.YamlScalarNode] }
function Is-MapObject($Value) { $Value -is [Collections.IDictionary] }
function Is-SeqObject($Value) { $Value -is [Collections.IEnumerable] -and -not ($Value -is [string]) -and -not (Is-MapObject $Value) }
function Tag-IsAllowed([string]$Tag) {
    if ([string]::IsNullOrEmpty($Tag) -or $Tag -in @('!','?')) { return $true }
    return $Tag -in @('!!str','!!map','!!seq','!!bool','!!int','!!float','!!null','tag:yaml.org,2002:str','tag:yaml.org,2002:map','tag:yaml.org,2002:seq','tag:yaml.org,2002:bool','tag:yaml.org,2002:int','tag:yaml.org,2002:float','tag:yaml.org,2002:null')
}
function Mark([object]$Event) { try { if ($null -ne $Event.Start) { return " línea $([int]$Event.Start.Line + 1), columna $([int]$Event.Start.Column + 1)" } } catch { }; return '' }
function Ensure-YamlAssembly {
    if (-not (Test-Path -LiteralPath $dependencyPath -PathType Leaf)) { Fail "Falta YamlDotNet 18.1.0 netstandard2.0 en $dependencyPath" }
    $item = Get-Item -LiteralPath $dependencyPath -Force
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Fail "La dependencia YAML es un enlace/reparse point: $dependencyPath" }
    $metadataPath = Join-Path (Split-Path $dependencyPath) 'dependency.json'
    if (-not (Test-Path -LiteralPath $metadataPath -PathType Leaf)) { Fail "Falta el inventario de integridad de YamlDotNet: $metadataPath" }
    try { $metadata = Get-Content -Raw -LiteralPath $metadataPath | ConvertFrom-Json } catch { Fail "Inventario de integridad inválido: $metadataPath" }
    if ($metadata.name -ne 'YamlDotNet' -or $metadata.version -ne '18.1.0' -or $metadata.asset -ne 'lib/netstandard2.0/YamlDotNet.dll' -or $metadata.assetBytes -ne $item.Length) { Fail "El inventario de YamlDotNet no coincide con el asset instalado: $dependencyPath" }
    $hash = (Get-FileHash -LiteralPath $dependencyPath -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($hash -ne ([string]$metadata.assetSha256).ToLowerInvariant()) { Fail "La integridad SHA-256 de YamlDotNet no coincide: $dependencyPath" }
    try { [Reflection.Assembly]::LoadFrom($dependencyPath) | Out-Null } catch { Fail "No se pudo cargar YamlDotNet 18.1.0: $($_.Exception.Message)" }
}
function Read-BoundedUtf8([string]$Path) {
    $stream = [IO.File]::Open($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
    $memory = [IO.MemoryStream]::new(); $buffer = [byte[]]::new(8192); $count = 0
    try { while (($read = $stream.Read($buffer, 0, $buffer.Length)) -gt 0) { $count += $read; if ($count -gt $maxYamlBytes) { Fail "YAML excede el límite de $maxYamlBytes bytes: $Path" }; $memory.Write($buffer,0,$read) }; $bytes = $memory.ToArray() } finally { $memory.Dispose(); $stream.Dispose() }
    try { $text = [Text.UTF8Encoding]::new($false,$true).GetString($bytes) } catch { Fail "YAML no está codificado como UTF-8 válido: $Path" }
    if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
    return $text
}
function Assert-EventTag([object]$Event, [string]$Path) {
    if ($Event -is [YamlDotNet.Core.Events.NodeEvent]) { if (-not $Event.Anchor.IsEmpty) { Fail "$Path$(Mark $Event): anchors no admitidos" }; if (-not (Tag-IsAllowed $Event.Tag)) { Fail "$Path$(Mark $Event): tag personalizado o no admitido '$($Event.Tag)'" } }
}
function Preflight-Yaml([string]$Text, [string]$Path) {
    $parser = [YamlDotNet.Core.Parser]::new([IO.StringReader]::new($Text)); $stack = [Collections.Generic.List[hashtable]]::new(); $documents = 0; $rootSeen = $false; $rootKind = ''; $ended = $false
    while ($parser.MoveNext()) {
        $event = $parser.Current; Assert-EventTag $event $Path
        if ($event -is [YamlDotNet.Core.Events.AnchorAlias]) { Fail "$Path$(Mark $event): aliases no admitidos" }
        if ($event -is [YamlDotNet.Core.Events.DocumentStart]) { $documents++; if ($documents -gt 1) { Fail "$Path$(Mark $event): se admite un solo documento YAML" }; continue }
        if ($event -is [YamlDotNet.Core.Events.MappingStart] -or $event -is [YamlDotNet.Core.Events.SequenceStart]) {
            if ($stack.Count -eq 0) { if ($rootSeen) { Fail "$Path$(Mark $event): más de una raíz YAML" }; $rootSeen = $true; $rootKind = if ($event -is [YamlDotNet.Core.Events.MappingStart]) {'map'} else {'seq'} }
            elseif ($stack[$stack.Count-1].kind -eq 'map' -and $stack[$stack.Count-1].expectKey) { Fail "$Path$(Mark $event): las claves deben ser escalares textuales" }
            if (($stack.Count + 1) -gt $maxYamlDepth) { Fail "$Path$(Mark $event): profundidad YAML superior a $maxYamlDepth" }
            if ($stack.Count -gt 0 -and $stack[$stack.Count-1].kind -eq 'map') { $stack[$stack.Count-1].expectKey = $false }
            [void]$stack.Add(@{ kind = if ($event -is [YamlDotNet.Core.Events.MappingStart]) {'map'} else {'seq'}; expectKey = ($event -is [YamlDotNet.Core.Events.MappingStart]); keys = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal) })
            continue
        }
        if ($event -is [YamlDotNet.Core.Events.Scalar]) {
            if ($stack.Count -eq 0) { if ($rootSeen) { Fail "$Path$(Mark $event): más de una raíz YAML" }; $rootSeen = $true; $rootKind = 'scalar' }
            elseif ($stack[$stack.Count-1].kind -eq 'map') { $frame = $stack[$stack.Count-1]; if ($frame.expectKey) { if ($event.Value -eq '<<' -and ([string]$event.Style -eq 'Plain' -or $event.Tag -in @('!!merge','tag:yaml.org,2002:merge'))) { Fail "$Path$(Mark $event): merge keys no admitidas" }; if (-not $frame.keys.Add([string]$event.Value)) { Fail "$Path$(Mark $event): clave duplicada '$($event.Value)'" }; $frame.expectKey = $false } else { $frame.expectKey = $true } }
            continue
        }
        if ($event -is [YamlDotNet.Core.Events.MappingEnd] -or $event -is [YamlDotNet.Core.Events.SequenceEnd]) { if ($stack.Count -eq 0) { Fail "$Path$(Mark $event): cierre YAML inesperado" }; $frame = $stack[$stack.Count-1]; if ($event -is [YamlDotNet.Core.Events.MappingEnd] -and -not $frame.expectKey) { Fail "$Path$(Mark $event): mapa con valor ausente" }; $stack.RemoveAt($stack.Count-1); if ($stack.Count -gt 0 -and $stack[$stack.Count-1].kind -eq 'map') { $stack[$stack.Count-1].expectKey = $true }; continue }
        if ($event -is [YamlDotNet.Core.Events.DocumentEnd]) { if ($stack.Count -ne 0) { Fail "$Path$(Mark $event): documento YAML sin cerrar" }; $ended = $true }
    }
    if ($documents -ne 1 -or -not $ended -or -not $rootSeen) { Fail "$Path`: documento YAML vacío o incompleto" }
    if ($rootKind -ne 'map') { Fail "$Path`: la raíz YAML debe ser un mapa" }
}
function Convert-YamlNode($Node) {
    if (Is-Map $Node) { $out = [ordered]@{}; foreach ($pair in $Node.Children.GetEnumerator()) { if (-not (Is-Scalar $pair.Key)) { Fail 'Las claves YAML deben ser escalares' }; $child = Convert-YamlNode $pair.Value; if (Is-Seq $pair.Value) { $out[[string]$pair.Key.Value] = [object[]]$child } else { $out[[string]$pair.Key.Value] = $child } }; return $out }
    if (Is-Seq $Node) { return ,([object[]]@($Node.Children | ForEach-Object { Convert-YamlNode $_ })) }
    if (Is-Scalar $Node) { $value=[string]$Node.Value; if ([string]$Node.Style -eq 'Plain' -and [string]::IsNullOrEmpty($value)) { return $null }; if ([string]$Node.Style -eq 'Plain' -and $value -match '^(?i:true|false)$') { return [bool]::Parse($value) }; if ([string]$Node.Style -eq 'Plain' -and $value -match '^(?i:null|~)$') { return $null }; if ([string]$Node.Style -eq 'Plain' -and $value -match '^-?[0-9]+$') { try { return [int64]$value } catch { return $value } }; return $value }
    Fail 'Nodo YAML no admitido.'
}
function Read-Yaml([string]$Path) {
    Ensure-YamlAssembly; $text = Read-BoundedUtf8 $Path; Preflight-Yaml $text $Path; $model = [YamlDotNet.RepresentationModel.YamlStream]::new()
    try { $model.Load([IO.StringReader]::new($text)) } catch { Fail "$Path`: sintaxis YAML inválida: $($_.Exception.Message)" }
    if ($model.Documents.Count -ne 1 -or -not (Is-Map $model.Documents[0].RootNode)) { Fail "$Path`: la raíz YAML debe ser un mapa" }
    return Convert-YamlNode $model.Documents[0].RootNode
}
function Has-Key($Map,[string]$Name) { Is-MapObject $Map -and $Map.Contains($Name) }
function Get-Field($Map,[string]$Name) { if (Has-Key $Map $Name) { return ,$Map[$Name] }; return $null }
function Require-Field($Map,[string]$Name,[string]$Path) { if (-not (Has-Key $Map $Name)) { Fail "$Path`: falta '$Name'" }; return ,$Map[$Name] }
function Assert-KnownKeys($Map,[string[]]$Allowed,[string]$Path) { foreach ($key in $Map.Keys) { if ($key -notin $Allowed) { Fail "$Path`: clave operativa desconocida '$key'" } } }
function Require-Map($Value,[string]$Path) { if (-not (Is-MapObject $Value)) { Fail "$Path`: se esperaba un mapa" }; return ,$Value }
function Require-Seq($Value,[string]$Path) { if (-not (Is-SeqObject $Value)) { $type=if($null -eq $Value){'<null>'}else{$Value.GetType().FullName}; Fail "$Path`: se esperaba una lista (recibido $type)" }; return ,([object[]]$Value) }
function Require-Text($Value,[string]$Path) { if ($null -eq $Value -or $Value -isnot [string] -or [string]::IsNullOrWhiteSpace($Value)) { Fail "$Path`: se esperaba texto no vacío" }; return [string]$Value }
function Assert-VersionOne($Value,[string]$Path) { if ([string]$Value -ne '1') { Fail "$Path`: version debe ser el entero 1" } }
function Text-List($Value,[string]$Path) { $items = Require-Seq $Value $Path; $out = [Collections.Generic.List[string]]::new(); foreach ($item in $items) { [void]$out.Add((Require-Text $item "$Path[]")) }; return @($out) }
function Unique-TextList($Value,[string]$Path) { $items = @(Text-List $Value $Path); $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal); foreach ($item in $items) { if (-not $seen.Add($item)) { Fail "$Path`: elemento duplicado '$item'" } }; return $items }
function Assert-Boolean($Value,[string]$Path,[bool]$MustBeTrue=$false) { if ($Value -isnot [bool]) { Fail "$Path`: se esperaba booleano true/false" }; if ($MustBeTrue -and -not $Value) { Fail "$Path`: debe ser true" }; return $Value }
function Assert-Rfc3339([string]$Value,[string]$Path) { if ([string]::IsNullOrWhiteSpace($Value) -or $Value -notmatch '(Z|[+-][0-9]{2}:[0-9]{2})$') { Fail "$Path`: debe ser RFC 3339 con offset" }; $parsed=[DateTimeOffset]::MinValue; if (-not [DateTimeOffset]::TryParse($Value,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$parsed)) { Fail "$Path`: fecha RFC 3339 inválida" }; return $parsed }
function Assert-RelativePath([string]$Path,[string]$Field,[string]$Root,[bool]$MustExist=$true) { if ([string]::IsNullOrWhiteSpace($Path) -or $Path.Contains('\') -or $Path.Contains(':') -or $Path.StartsWith('/') -or $Path -match '(^|/)\.($|/)' -or $Path -match '(^|/)\.\.($|/)' -or $Path -match '(^|/)//|/$') { Fail "$Field`: ruta insegura '$Path'" }; $candidate=FullPath (Join-Path $Root ($Path.Replace('/',[IO.Path]::DirectorySeparatorChar))); $base=Normalize-Root $Root; if (-not $candidate.StartsWith($base+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) { Fail "$Field`: ruta fuera de la raíz" }; if ($MustExist -and -not(Test-Path -LiteralPath $candidate -PathType Leaf)) { Fail "$Field`: falta archivo '$Path'" }; if (Test-Path -LiteralPath $candidate) { $item=Get-Item -LiteralPath $candidate -Force; if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0) { Fail "$Field`: ruta insegura '$Path'" } }; return $candidate }
function Read-Workflow([string]$Root) {
    $path=Join-Path $Root '.harness/workflow.yaml'; $w=Require-Map (Read-Yaml $path) $path; Assert-KnownKeys $w @('version','project','states','transitions','human_gates','definition_of_ready','definition_of_done','publication','metadata','notes','validation','blocking','decision_validation') $path; Assert-VersionOne (Require-Field $w 'version' $path) "$path.version"; $project=Require-Text (Require-Field $w 'project' $path) "$path.project"; $states=Unique-TextList (Require-Field $w 'states' $path) "$path.states"; $stateSet=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal); foreach($s in $states){$stateSet.Add($s)|Out-Null}; $transitions=Require-Map (Require-Field $w 'transitions' $path) "$path.transitions"; foreach($from in $transitions.Keys){if(-not $stateSet.Contains($from)){Fail "$path.transitions`: estado inexistente '$from'"}; foreach($to in @(Unique-TextList $transitions[$from] "$path.transitions.$from")){if(-not $stateSet.Contains($to)){Fail "$path.transitions.$from`: destino inexistente '$to'"}}}
    $gates=Require-Map (Require-Field $w 'human_gates' $path) "$path.human_gates"; Assert-KnownKeys $gates @('approval_mode','architecture','specification','publication') "$path.human_gates"; $modeNode=Get-Field $gates 'approval_mode'; $mode='never'; if($null -eq $modeNode){$script:Warnings.Add("$path.human_gates.approval_mode ausente; se aplica compatibilidad fail-closed 'never'.")|Out-Null}else{$mode=Require-Text $modeNode "$path.human_gates.approval_mode";if($mode -cnotin @('ask','never')){Fail "$path.human_gates.approval_mode`: debe ser exactamente 'ask' o 'never'"}}
    $arch=Require-Map (Require-Field $gates 'architecture' $path) "$path.human_gates.architecture"; Assert-KnownKeys $arch @('required_when','validation_enabled','required_in') "$path.human_gates.architecture"; $archEnabled=$false;if(Has-Key $arch 'validation_enabled'){$archEnabled=Assert-Boolean $arch.validation_enabled "$path.human_gates.architecture.validation_enabled"};$archIn=if(Has-Key $arch 'required_in'){Unique-TextList $arch.required_in "$path.human_gates.architecture.required_in"}elseif($archEnabled){Fail "$path.human_gates.architecture.required_in`: obligatorio cuando validation_enabled=true"}else{@()}
    $spec=Require-Map (Require-Field $gates 'specification' $path) "$path.human_gates.specification";Assert-KnownKeys $spec @('required','required_in') "$path.human_gates.specification";Assert-Boolean (Require-Field $spec 'required' $path) "$path.human_gates.specification.required" $true|Out-Null;$specIn=if(Has-Key $spec 'required_in'){Unique-TextList $spec.required_in "$path.human_gates.specification.required_in"}else{@('implementation','verification','publication_review','done')|Where-Object{$stateSet.Contains($_)}}
    $pub=Require-Map (Require-Field $gates 'publication' $path) "$path.human_gates.publication";Assert-KnownKeys $pub @('required','required_in') "$path.human_gates.publication";Assert-Boolean (Require-Field $pub 'required' $path) "$path.human_gates.publication.required" $true|Out-Null;$pubIn=if(Has-Key $pub 'required_in'){Unique-TextList $pub.required_in "$path.human_gates.publication.required_in"}else{@('done')|Where-Object{$stateSet.Contains($_)}}
    $phaseRules=$null;if((Has-Key $w 'validation') -and ($null -ne $w.validation)){ $validation=Require-Map $w.validation "$path.validation";Assert-KnownKeys $validation @('phase_rules') "$path.validation";$phaseRules=Require-Map (Require-Field $validation 'phase_rules' $path) "$path.validation.phase_rules";foreach($state in $states){if(-not(Has-Key $phaseRules $state)){Fail "$path.validation.phase_rules`: falta regla para '$state'"}}foreach($key in $phaseRules.Keys){if($key -notin $states){Fail "$path.validation.phase_rules`: fase inexistente '$key'"}}}
    $blockingCodes = @('needs-human-decision','external-dependency','blocked-by-architecture','needs-more-discovery','verification-failed','change-approval-required')
    if (Has-Key $w 'blocking') { $blocking = Require-Map $w.blocking "$path.blocking"; Assert-KnownKeys $blocking @('codes') "$path.blocking"; $blockingCodes = Unique-TextList (Require-Field $blocking 'codes' "$path.blocking") "$path.blocking.codes"; foreach($code in $blockingCodes){ if($code -notin @('needs-human-decision','external-dependency','blocked-by-architecture','needs-more-discovery','verification-failed','change-approval-required')) { Fail "BLOCKER_CODE_INVALID: $path.blocking.codes: código desconocido '$code'" } } }
    $legacyIds = @(); if (Has-Key $w 'decision_validation') { $dv=Require-Map $w.decision_validation "$path.decision_validation"; Assert-KnownKeys $dv @('legacy_ids') "$path.decision_validation"; if (Has-Key $dv 'legacy_ids') { $legacyIds=Unique-TextList $dv.legacy_ids "$path.decision_validation.legacy_ids" } }
    return [pscustomobject]@{Project=$project;States=$states;StateSet=$stateSet;Transitions=$transitions;ApprovalMode=$mode;SpecIn=@($specIn);PubIn=@($pubIn);ArchEnabled=$archEnabled;ArchIn=@($archIn);PhaseRules=$phaseRules;Path=$path;BlockingCodes=@($blockingCodes);LegacyIds=@($legacyIds)}
}
function Check-Markers([string]$Root,[bool]$TemplateMode){if($TemplateMode){return};foreach($r in @('AGENTS.md','.harness/project.yaml','features.yaml','progress/current.yaml')){if((Get-Content -Raw -LiteralPath (Join-Path $Root $r))-match '\{\{(PROJECT_NAME|DATE)\}\}'){Fail "Quedan marcadores sin inicializar en $r. Ejecutá init."}}}
function Get-FeatureMap($FeatureDoc,[string]$Path){Assert-KnownKeys $FeatureDoc @('version','project','status','features') $Path;Assert-VersionOne (Require-Field $FeatureDoc 'version' $Path) "$Path.version";$list=Require-Seq (Require-Field $FeatureDoc 'features' $Path) "$Path.features";$result=[ordered]@{};foreach($entry in $list){$m=Require-Map $entry "$Path.features[]";Assert-KnownKeys $m @('id','name','status','priority','depends_on') "$Path.features[]";$id=Require-Text (Require-Field $m 'id' $Path) "$Path.features[].id";if($result.Contains($id)){Fail "$Path`: id duplicado '$id'"};$result[$id]=$m};return $result}
function Get-Bundle([string]$Root,[string]$Active){
    $names=@('acceptance.md','design.md','requirements.md','tasks.md','test-plan.md');$rows=[Collections.Generic.List[string]]::new();$files=[Collections.Generic.List[object]]::new()
    foreach($name in ($names|Sort-Object)){$relative="specs/features/$Active/$name";$path=Assert-RelativePath $relative "bundle.$name" $Root;$bytes=[IO.File]::ReadAllBytes($path);if($name -eq 'tasks.md'){$text=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);$text=[regex]::Replace($text,'(?m)^(- \[)[ x](\] TASK-[0-9]{3,})','$1 $2');$bytes=[Text.UTF8Encoding]::new($false).GetBytes($text)};$hash=Get-Sha256Hex $bytes;[void]$files.Add([pscustomobject]@{Path=$relative;Bytes=$bytes.Length;Sha256=$hash});[void]$rows.Add("$hash`t$($bytes.Length)`t$relative`n")}
    $digest=Get-Sha256Hex ([Text.UTF8Encoding]::new($false).GetBytes(($rows-join '')));return [pscustomobject]@{Digest=$digest;Files=@($files)}
}
function Assert-ApprovalMetadata($Map,[string]$Name,[string]$Path){$status=Require-Text (Require-Field $Map 'status' $Path) "$Path.status";if($status -notin @('pending','approved','rejected')){Fail "$Path.status`: valor inválido '$status'"};if($status -ne 'approved'){return $null};$by=Require-Text (Require-Field $Map 'approved_by' $Path) "$Path.approved_by";$at=Require-Text (Require-Field $Map 'approved_at' $Path) "$Path.approved_at";Assert-Rfc3339 $at "$Path.approved_at"|Out-Null;$ref=Require-Text (Require-Field $Map 'reference' $Path) "$Path.reference";return [pscustomobject]@{Name=$Name;ApprovedBy=$by;Reference=$ref}}
function Test-ApprovalForTransition($Progress,[string]$Name,[string]$Root,[string]$Active){$map=Get-Field $Progress.approvals $Name;if(-not(Is-MapObject $map)){return $false};try{$result=if($Name-eq'specification'){Validate-SpecApproval $map 'progress.approvals.specification' $Root $Active}else{Assert-ApprovalMetadata $map $Name "progress.approvals.$Name"};return $null-ne$result}catch{return $false}}
function Validate-SpecApproval($Map,[string]$Path,[string]$Root,[string]$Active){$base=Assert-ApprovalMetadata $Map 'specification' $Path;if($null -eq $base){Fail "$Path.status`: debe ser approved"};$bundle=Require-Map (Require-Field $Map 'bundle' $Path) "$Path.bundle";Assert-KnownKeys $bundle @('algorithm','digest','files') "$Path.bundle";if((Require-Text $bundle.algorithm "$Path.bundle.algorithm") -cne 'sha256'){Fail "$Path.bundle.algorithm`: debe ser sha256"};$digest=Require-Text $bundle.digest "$Path.bundle.digest";if($digest -notmatch '^[0-9a-f]{64}$'){Fail "$Path.bundle.digest`: SHA-256 inválido"};$expected=Get-Bundle $Root $Active;$list=Require-Seq $bundle.files "$Path.bundle.files";if($list.Count -ne $expected.Files.Count){Fail "$Path.bundle.files`: inventario distinto del contrato vigente"};for($i=0;$i -lt $list.Count;$i++){$f=Require-Map $list[$i] "$Path.bundle.files[$i]";Assert-KnownKeys $f @('path','bytes','sha256') "$Path.bundle.files[$i]";if((Require-Text $f.path "$Path.bundle.files[$i].path") -cne $expected.Files[$i].Path -or [int64]$f.bytes -ne $expected.Files[$i].Bytes -or (Require-Text $f.sha256 "$Path.bundle.files[$i].sha256") -cne $expected.Files[$i].Sha256){Fail "$Path.bundle.files[$i]`: hash, bytes u orden no coinciden"}};if($digest -cne $expected.Digest){Fail "$Path.bundle.digest`: approval desactualizada; esperado $($expected.Digest)"};$review=Require-Map (Require-Field $Map 'review' $Path) "$Path.review";Assert-KnownKeys $review @('status','reviewed_by','reviewed_at','reference','specification_digest') "$Path.review";if((Require-Text $review.status "$Path.review.status") -cne 'pass'){Fail "$Path.review.status`: debe ser pass"};$reviewer=Require-Text $review.reviewed_by "$Path.review.reviewed_by";Assert-Rfc3339 (Require-Text $review.reviewed_at "$Path.review.reviewed_at") "$Path.review.reviewed_at"|Out-Null;Require-Text $review.reference "$Path.review.reference"|Out-Null;if((Require-Text $review.specification_digest "$Path.review.specification_digest") -cne $digest){Fail "$Path.review.specification_digest`: no coincide con bundle"};return [pscustomobject]@{ApprovedBy=$base.ApprovedBy;Reviewer=$reviewer;Digest=$digest}}
function Get-History([string]$Root,$Workflow,$Features,$Progress){$path=Join-Path $Root 'progress/history.yaml';if(-not(Test-Path -LiteralPath $path -PathType Leaf)){Fail "$path`: falta history schema 1; adopción manual requerida"};$h=Require-Map (Read-Yaml $path) $path;Assert-KnownKeys $h @('schema','events') $path;Assert-VersionOne (Require-Field $h 'schema' $path) "$path.schema";$events=Require-Seq (Require-Field $h 'events' $path) "$path.events";if($events.Count -eq 0){Fail "$path.events`: no puede estar vacío"};$ids=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$last=$null;$by=[ordered]@{};foreach($e in $events){$m=Require-Map $e "$path.events[]";$kind=Require-Text (Require-Field $m 'kind' $path) "$path.events[].kind";$allowed=if($kind -eq 'migration'){@('id','kind','feature','from','to','occurred_at','actor','reference','prior_history','note')}elseif($kind -eq 'transition'){@('id','kind','feature','from','to','occurred_at','actor','reference','gate_references')}else{Fail "$path.events[].kind`: tipo inválido '$kind'"};Assert-KnownKeys $m $allowed "$path.events[]";$id=Require-Text $m.id "$path.events[].id";if(-not$ids.Add($id)){Fail "$path.events`: ID repetido '$id'"};if(($kind -eq 'migration' -and $id -notmatch '^MIG-[0-9]{3,}$') -or ($kind -eq 'transition' -and $id -notmatch '^TRN-[0-9]{3,}$')){Fail "$path.events[$id].id`: formato inválido"};$feature=Require-Text $m.feature "$path.events[$id].feature";if(-not$Features.Contains($feature)){Fail "$path.events[$id].feature`: feature inexistente '$feature'"};$date=Assert-Rfc3339 (Require-Text $m.occurred_at "$path.events[$id].occurred_at") "$path.events[$id].occurred_at";if($null-ne$last-and$date-lt$last){Fail "$path.events[$id].occurred_at`: tiempo regresivo"};$last=$date;Require-Text $m.actor "$path.events[$id].actor"|Out-Null;Require-Text $m.reference "$path.events[$id].reference"|Out-Null;$to=Require-Text $m.to "$path.events[$id].to";if(-not$Workflow.StateSet.Contains($to)){Fail "$path.events[$id].to`: estado inexistente '$to'"};if($kind -eq 'migration'){if($null-ne(Get-Field $m 'from')){Fail "$path.events[$id].from`: migration debe tener from null"};if((Require-Text $m.prior_history "$path.events[$id].prior_history") -cne 'unknown'){Fail "$path.events[$id].prior_history`: solo se admite unknown"};if($by.Contains($feature)){Fail "$path.events[$id]`: migration duplicada"};$by[$feature]=[pscustomobject]@{Migration=$m;Transitions=[Collections.Generic.List[object]]::new()}}else{$from=Require-Text $m.from "$path.events[$id].from";if(-not$by.Contains($feature)){Fail "$path.events[$id]`: falta migration inicial"};$gates=Unique-TextList $m.gate_references "$path.events[$id].gate_references";[void]$by[$feature].Transitions.Add([pscustomobject]@{Event=$m;From=$from;To=$to;Gates=$gates})}}
    $active=Require-Text $Progress.active_feature 'progress.active_feature';if(-not$by.Contains($active)){Fail "$path`: no existe historia para feature activa '$active'"};$state=$by[$active].Migration.to;foreach($tr in $by[$active].Transitions){if(-not(Has-Key $Workflow.Transitions $tr.From)-or$tr.To-notin@(Text-List $Workflow.Transitions[$tr.From] "$Workflow.Path.transitions.$($tr.From)")){Fail "$path.events[$($tr.Event.id)]`: arista no declarada"};if($tr.From-cne$state){Fail "$path.events[$($tr.Event.id)].from`: discontinuidad"};$state=$tr.To};if($state-cne$Progress.phase){Fail "$path`: replay termina en '$state', pero progress.phase es '$($Progress.phase)'"};if($Features[$active].status-cne$state){Fail "$path`: replay no coincide con features.yaml"};return [pscustomobject]@{Events=$events;Active=$active;State=$state;ByFeature=$by}
}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){$fp=Join-Path $Root 'features.yaml';$fd=Require-Map (Read-Yaml $fp) $fp;$features=Get-FeatureMap $fd $fp;$project=Require-Text $fd.project "$fp.project";if($project-cne$Workflow.Project){Fail "$fp.project`: no coincide con workflow.project"};$pp=Join-Path $Root 'progress/current.yaml';$progress=Require-Map (Read-Yaml $pp) $pp;if((Require-Text $progress.project "$pp.project")-cne$Workflow.Project){Fail "$pp.project`: no coincide con workflow.project"};$active=Require-Text $progress.active_feature "$pp.active_feature";if(-not$features.Contains($active)){Fail "$pp.active_feature`: feature inexistente '$active'"};$phase=Require-Text $progress.phase "$pp.phase";if(-not$Workflow.StateSet.Contains($phase)){Fail "$pp.phase`: fase inexistente '$phase'"};if($features[$active].status-cne$phase){Fail "$pp.phase`: no coincide con features.yaml"};foreach($entry in $features.Values){foreach($dep in @(Unique-TextList $entry.depends_on "$fp.features[$($entry.id)].depends_on")){if(-not$features.Contains($dep)){Fail "$fp.features[$($entry.id)].depends_on`: dependencia inexistente '$dep'"}}};$history=Get-History $Root $Workflow $features $progress;$approvals=Require-Map $progress.approvals "$pp.approvals";$gateResults=[Collections.Generic.List[object]]::new();if($phase-in$Workflow.SpecIn){[void]$gateResults.Add((Validate-SpecApproval (Require-Map $approvals.specification "$pp.approvals.specification") "$pp.approvals.specification" $Root $active))};if($phase-in$Workflow.PubIn){[void]$gateResults.Add((Assert-ApprovalMetadata (Require-Map $approvals.publication "$pp.approvals.publication") 'publication' "$pp.approvals.publication"))};if($Workflow.ArchEnabled-and$phase-in$Workflow.ArchIn){$arch=Require-Map $approvals.architecture "$pp.approvals.architecture";$app=Require-Text $arch.applicability "$pp.approvals.architecture.applicability";if($app-eq'required'){[void]$gateResults.Add((Assert-ApprovalMetadata $arch 'architecture' "$pp.approvals.architecture"))}elseif($app-eq'not_required'){Require-Text $arch.rationale "$pp.approvals.architecture.rationale"|Out-Null}else{Fail "$pp.approvals.architecture.applicability`: valor inválido '$app'"}}
    if($phase-in@('implementation','verification','publication_review','done')){$execution=Require-Map $progress.execution "$pp.execution";Require-Text $execution.implemented_by "$pp.execution.implemented_by"|Out-Null};$quality=$progress.quality;if($phase-in@('verification','publication_review','done')){if(-not(Is-MapObject $quality)){Fail "$pp.quality`: revisión de implementación obligatoria"};if((Require-Text $quality.status "$pp.quality.status")-cne'pass'){Fail "$pp.quality.status`: debe ser pass"};Require-Text $quality.reviewed_by "$pp.quality.reviewed_by"|Out-Null;Assert-Rfc3339 (Require-Text $quality.reviewed_at "$pp.quality.reviewed_at") "$pp.quality.reviewed_at"|Out-Null;Require-Text $quality.reference "$pp.quality.reference"|Out-Null;if((Require-Text $quality.specification_digest "$pp.quality.specification_digest")-ne(Get-Bundle $Root $active).Digest){Fail "$pp.quality.specification_digest`: no coincide con specification vigente"}}
    if($phase-in@('verification','publication_review','done')){$spec=$approvals.specification;$implementer=$progress.execution.implemented_by;$specApprover=$spec.approved_by;if($implementer-eq$spec.review.reviewed_by-or$implementer-eq$specApprover){Fail "$pp.execution.implemented_by`: coincide con reviewer/approver"};if($spec.review.reviewed_by-eq$specApprover){Fail "$pp.approvals.specification.review`: reviewer y approver deben ser distintos"};if($phase-in@('verification','publication_review','done')-and$quality.reviewed_by-in@($implementer,$specApprover)){Fail "$pp.quality.reviewed_by`: coincide con implementador/aprobador"}}
    return [pscustomobject]@{Progress=$progress;Features=$features;History=$history;Active=$active;Phase=$phase}
}
function Assert-PhaseArtifacts([string]$Root,$Workflow,[string]$Phase,[string]$Active){
    if($null -eq $Workflow.PhaseRules -or -not (Has-Key $Workflow.PhaseRules $Phase)){return}
    $rule=Require-Map $Workflow.PhaseRules[$Phase] "$($Workflow.Path).validation.phase_rules.$Phase"
    Assert-KnownKeys $rule @('required_artifacts') "$($Workflow.Path).validation.phase_rules.$Phase"
    $required=Unique-TextList (Require-Field $rule 'required_artifacts' "$($Workflow.Path).validation.phase_rules.$Phase") "$($Workflow.Path).validation.phase_rules.$Phase.required_artifacts"
    foreach($artifact in $required){$candidate=if($artifact-eq'evidence.md'){"specs/features/$Active/evidence.md"}else{"specs/features/$Active/$artifact"};Assert-RelativePath $candidate "$($Workflow.Path).validation.phase_rules.$Phase.required_artifacts" $Root|Out-Null}
}
$script:BaseValidateState=${function:Validate-State}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){try{$result=& $script:BaseValidateState $Root $Workflow $SkipJournal}catch{$message=$_.Exception.Message;if($message-match '\.phase: se esperaba texto no vacío'){Fail "$Root\progress\current.yaml.phase`: no declara phase"};if($message-match "fase inexistente '([^']+)'"){$bad=$Matches[1];Fail "$Root\progress\current.yaml.phase`: Fase desconocida '$bad'"};if($message-match 'current\.yaml\.approvals\.specification.*(?:status|se esperaba un mapa)'){Fail "$Root\progress\current.yaml.approvals.specification`: la fase requiere aprobación de especificación"};if($message-match 'current\.yaml\.approvals\.publication.*(?:status|se esperaba un mapa)'){Fail "$Root\progress\current.yaml.approvals.publication`: done requiere aprobación de publicación"};throw};if($result.Phase-in$Workflow.PubIn){$pub=Assert-ApprovalMetadata (Require-Map $result.Progress.approvals.publication "$Root\progress\current.yaml.approvals.publication") 'publication' "$Root\progress\current.yaml.approvals.publication";if($null-eq$pub){Fail "$Root\progress\current.yaml.approvals.publication`: done requiere aprobación de publicación"}};if($Workflow.ArchEnabled-and$result.Phase-in$Workflow.ArchIn){$arch=Require-Map $result.Progress.approvals.architecture "$Root\progress\current.yaml.approvals.architecture";if((Require-Text $arch.applicability "$Root\progress\current.yaml.approvals.architecture.applicability")-eq'required'){$approval=Assert-ApprovalMetadata $arch 'architecture' "$Root\progress\current.yaml.approvals.architecture";if($null-eq$approval){Fail "$Root\progress\current.yaml.approvals.architecture.status`: debe ser approved en fase $($result.Phase)"}}};Assert-PhaseArtifacts $Root $Workflow $result.Phase $result.Active;return $result}
$script:BaseAssertRelativePath=${function:Assert-RelativePath}
function Assert-RelativePath([string]$Path,[string]$Field,[string]$Root,[bool]$MustExist=$true){$candidate=& $script:BaseAssertRelativePath $Path $Field $Root $MustExist;$cursor=$candidate;while($true){if(Test-Path -LiteralPath $cursor){$item=Get-Item -LiteralPath $cursor -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){Fail "$Field`: ruta insegura '$Path'"}};$parent=Split-Path -Parent $cursor;if([string]::IsNullOrWhiteSpace($parent)-or$parent-eq$cursor){break};$cursor=$parent};return $candidate}
$script:BaseGetHistory=${function:Get-History}
function Get-History([string]$Root,$Workflow,$Features,$Progress){$result=& $script:BaseGetHistory $Root $Workflow $Features $Progress;foreach($event in $result.Events){if((Require-Text $event.kind 'history.events[].kind')-eq'migration'){if(-not(Has-Key $event 'from')){Fail 'history.events[].from`: migration debe declarar from: null'}}else{$to=Require-Text $event.to 'history.events[].to';$expected=@();if($to-in$Workflow.SpecIn){$expected+='approvals.specification'};if($to-in$Workflow.PubIn){$expected+='approvals.publication'};if($Workflow.ArchEnabled-and$to-in$Workflow.ArchIn){$expected+='approvals.architecture'};$actual=Unique-TextList $event.gate_references 'history.events[].gate_references';foreach($gate in $expected){if($gate-notin$actual){Fail "history.events[$($event.id)].gate_references`: falta '$gate'"}};foreach($gate in $actual){if($gate-notin$expected){Fail "history.events[$($event.id)].gate_references`: referencia no exigida '$gate'"}}}};return $result}
function Assert-TransitionAncestors([string]$Root){$cursor=FullPath $Root;while($true){if(Test-Path -LiteralPath $cursor){$item=Get-Item -LiteralPath $cursor -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){Fail "Ruta insegura por reparse point: $cursor"}};$parent=Split-Path -Parent $cursor;if([string]::IsNullOrWhiteSpace($parent)-or$parent-eq$cursor){break};$cursor=$parent}}
$script:ActorCheckedValidateState=${function:Validate-State}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){$result=& $script:ActorCheckedValidateState $Root $Workflow $SkipJournal;if($result.Phase-in@('verification','publication_review','done')){$approvers=[Collections.Generic.List[string]]::new();$spec=Require-Map $result.Progress.approvals.specification "$Root\progress\current.yaml.approvals.specification";[void]$approvers.Add((Require-Text $spec.approved_by "$Root\progress\current.yaml.approvals.specification.approved_by"));$arch=Require-Map $result.Progress.approvals.architecture "$Root\progress\current.yaml.approvals.architecture";if((Require-Text $arch.applicability "$Root\progress\current.yaml.approvals.architecture.applicability")-eq'required'){[void]$approvers.Add((Require-Text $arch.approved_by "$Root\progress\current.yaml.approvals.architecture.approved_by"))};if($result.Phase-in$Workflow.PubIn){$pub=Require-Map $result.Progress.approvals.publication "$Root\progress\current.yaml.approvals.publication";[void]$approvers.Add((Require-Text $pub.approved_by "$Root\progress\current.yaml.approvals.publication.approved_by"))};$implementer=Require-Text $result.Progress.execution.implemented_by "$Root\progress\current.yaml.execution.implemented_by";foreach($actor in $approvers){if($implementer.Equals($actor,[StringComparison]::Ordinal)){Fail "$Root\progress\current.yaml.execution.implemented_by`: coincide con un aprobador aplicable"}};if($null-ne$result.Progress.quality){$qualityReviewer=Require-Text $result.Progress.quality.reviewed_by "$Root\progress\current.yaml.quality.reviewed_by";foreach($actor in $approvers){if($qualityReviewer.Equals($actor,[StringComparison]::Ordinal)){Fail "$Root\progress\current.yaml.quality.reviewed_by`: coincide con un aprobador aplicable"}}}};return $result}
$script:AllActorCheckedState=${function:Validate-State}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){$result=& $script:AllActorCheckedState $Root $Workflow $SkipJournal;if($result.Phase-in@('implementation','verification','publication_review','done')){$approvers=[Collections.Generic.List[string]]::new();$spec=Require-Map $result.Progress.approvals.specification "$Root\progress\current.yaml.approvals.specification";[void]$approvers.Add((Require-Text $spec.approved_by "$Root\progress\current.yaml.approvals.specification.approved_by"));$arch=Require-Map $result.Progress.approvals.architecture "$Root\progress\current.yaml.approvals.architecture";if((Require-Text $arch.applicability "$Root\progress\current.yaml.approvals.architecture.applicability")-eq'required'){[void]$approvers.Add((Require-Text $arch.approved_by "$Root\progress\current.yaml.approvals.architecture.approved_by"))};if($result.Phase-in$Workflow.PubIn){$pub=Require-Map $result.Progress.approvals.publication "$Root\progress\current.yaml.approvals.publication";[void]$approvers.Add((Require-Text $pub.approved_by "$Root\progress\current.yaml.approvals.publication.approved_by"))};$implementer=Require-Text $result.Progress.execution.implemented_by "$Root\progress\current.yaml.execution.implemented_by";foreach($actor in $approvers){if($implementer.Equals($actor,[StringComparison]::Ordinal)){Fail "$Root\progress\current.yaml.execution.implemented_by`: coincide con un aprobador aplicable"}};if($result.Phase-in@('verification','publication_review','done')-and$null-ne$result.Progress.quality){$qualityReviewer=Require-Text $result.Progress.quality.reviewed_by "$Root\progress\current.yaml.quality.reviewed_by";foreach($actor in $approvers){if($qualityReviewer.Equals($actor,[StringComparison]::Ordinal)){Fail "$Root\progress\current.yaml.quality.reviewed_by`: coincide con un aprobador aplicable"}}}};return $result}
$script:BaseAssertApprovalMetadata=${function:Assert-ApprovalMetadata}
function Assert-ApprovalMetadata($Map,[string]$Name,[string]$Path){$status=Require-Text (Require-Field $Map 'status' $Path) "$Path.status";if($status-cnotin @('pending','approved','rejected')){Fail "$Path.status`: valor inválido '$status'"};& $script:BaseAssertApprovalMetadata $Map $Name $Path}
function Assert-ManagedStateFiles([string]$Root){foreach($relative in @('.harness/workflow.yaml','.harness/project.yaml','features.yaml','progress/current.yaml','progress/history.yaml')){$path=Join-Path $Root $relative;if(Test-Path -LiteralPath $path -PathType Leaf){$item=Get-Item -LiteralPath $path -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){Fail "Ruta administrada insegura por reparse point: $relative"};Assert-TransitionAncestors (Split-Path -Parent $path)}}}
$script:ManagedPathValidateState=${function:Validate-State}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){Assert-ManagedStateFiles $Root;$result=& $script:ManagedPathValidateState $Root $Workflow $SkipJournal;return $result}
function Get-JournalPath([string]$Root){Join-Path $Root 'progress/transition.pending.yaml'}
function Get-StagingPath([string]$Root){Join-Path $Root 'progress/.transition-pending'}
function Get-Hash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Recovery-Diagnosis([string]$Root){$journal=Get-JournalPath $Root;if(-not(Test-Path -LiteralPath $journal -PathType Leaf)){Fail 'progress/.transition-pending: staging sin journal'};$j=Require-Map (Read-Yaml $journal) $journal;$targets=Require-Seq $j.targets "$journal.targets";$before=$true;$after=$true;foreach($t in $targets){$p=Assert-RelativePath (Require-Text $t.path "$journal.targets[].path") "$journal.targets[].path" $Root;$hash=if(Test-Path -LiteralPath $p){Get-Hash $p}else{''};if($hash-cne(Require-Text $t.before_sha256 "$journal.targets[].before_sha256")){ $before=$false };if($hash-cne(Require-Text $t.after_sha256 "$journal.targets[].after_sha256")){ $after=$false }};if($before){Write-Error 'RECOVERY_BEFORE_VALID: todos los targets coinciden con before; limpiar manualmente staging y journal.'}elseif($after){Write-Error 'RECOVERY_AFTER_VALID: todos los targets coinciden con after; limpiar manualmente staging y journal.'}else{Write-Error 'RECOVERY_MIXED_OR_UNKNOWN: targets mezclados o desconocidos; no limpiar automáticamente.'}}
function Assert-NoRecovery([string]$Root,[bool]$SkipJournal){$journal=Get-JournalPath $Root;$stage=Get-StagingPath $Root;$hasJournal=Test-Path -LiteralPath $journal -PathType Leaf;$hasStage=Test-Path -LiteralPath $stage -PathType Container;if((-not $SkipJournal) -and ($hasJournal -or $hasStage)){if($hasJournal){Recovery-Diagnosis $Root}else{Fail 'progress/.transition-pending: staging sin journal'};Fail "$journal`: recuperación manual requerida"}}
function Replace-ActiveStatus([string]$Text,[string]$Active,[string]$Phase){$pattern='(?ms)(-\s+id:\s*'+[regex]::Escape($Active)+'\s*\r?\n.*?^\s*status:)\s*[^\r\n]+';$new=[regex]::Replace($Text,$pattern,'$1 '+$Phase,1);if($new-eq$Text){Fail "features.yaml`: no se pudo actualizar status de '$Active'"};return $new}
function Replace-Phase([string]$Text,[string]$Phase){$new=[regex]::Replace($Text,'(?m)^phase:\s*[^\r\n]+','phase: '+$Phase,1);if($new-eq$Text){Fail 'progress/current.yaml: no se pudo actualizar phase'};return $new}
function Quote-Yaml([string]$Value){"'"+$Value.Replace("'","''")+"'"}
function Append-Transition([string]$Text,[string]$Id,[string]$Active,[string]$From,[string]$To,[string]$Occurred,[string]$Actor,[string]$Reference,[string[]]$Gates){$effective=@($Gates);if(-not[string]::IsNullOrWhiteSpace($script:ChangeOriginDigestToPersist)){$effective+=('change-origin:'+$script:ChangeOriginDigestToPersist)};$gateText=if($effective.Count-eq0){'[]'}else{'['+(($effective|ForEach-Object{Quote-Yaml $_})-join ', ')+']'};$suffix="`n  - id: $Id`n    kind: transition`n    feature: $(Quote-Yaml $Active)`n    from: $(Quote-Yaml $From)`n    to: $(Quote-Yaml $To)`n    occurred_at: $(Quote-Yaml $Occurred)`n    actor: $(Quote-Yaml $Actor)`n    reference: $(Quote-Yaml $Reference)`n    gate_references: $gateText`n";return $Text.TrimEnd("`r","`n")+$suffix}
function Write-Bytes([string]$Path,[byte[]]$Bytes){$parent=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};[IO.File]::WriteAllBytes($Path,$Bytes)}
$script:BaseWriteBytes=${function:Write-Bytes}
function Write-Bytes([string]$Path,[byte[]]$Bytes){Assert-TransitionAncestors (Split-Path -Parent $Path);& $script:BaseWriteBytes $Path $Bytes}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){if([string]::IsNullOrWhiteSpace($Destination)-or[string]::IsNullOrWhiteSpace($ActorValue)-or[string]::IsNullOrWhiteSpace($ReferenceValue)){Fail 'transition requiere -To, -Actor y -Reference no blancos.'};Assert-NoRecovery $Root $false;$workflow=Read-Workflow $Root;$baseline=Validate-State $Root $workflow $false;if(-not$workflow.StateSet.Contains($Destination)){Fail "-To`: fase inexistente '$Destination'"};if(-not(Has-Key $workflow.Transitions $baseline.Phase)-or$Destination-notin@(Text-List $workflow.Transitions[$baseline.Phase] "$($workflow.Path).transitions.$($baseline.Phase)")){Fail "transition`: arista no declarada $($baseline.Phase) → $Destination"};if($Destination-in$workflow.SpecIn-and-not(Test-ApprovalForTransition $baseline.Progress 'specification' $Root $baseline.Active)){if($workflow.ApprovalMode-eq'ask'){Fail "APPROVAL_REQUEST: feature $($baseline.Active), destino $Destination, puerta specification; registre approval válida para el digest vigente."}else{Fail "APPROVAL_PROHIBITED: feature $($baseline.Active), destino $Destination, puerta specification; approval válida ausente y la interacción está prohibida."}};if($Destination-in$workflow.PubIn-and-not(Test-ApprovalForTransition $baseline.Progress 'publication' $Root $baseline.Active)){if($workflow.ApprovalMode-eq'ask'){Fail "APPROVAL_REQUEST: feature $($baseline.Active), destino $Destination, puerta publication; registre approval válida antes de reintentar."}else{Fail "APPROVAL_PROHIBITED: feature $($baseline.Active), destino $Destination, puerta publication; approval válida ausente y la interacción está prohibida."}};if($Destination-in@('verification','publication_review','done')){$q=$baseline.Progress.quality;if(-not(Is-MapObject $q)-or[ string ]$q.status-ne'pass'){Fail "transition hacia $Destination`: quality.status debe ser pass antes de escribir"};if((Require-Text $q.specification_digest "$($Root)\progress\quality.specification_digest")-ne(Get-Bundle $Root $baseline.Active).Digest){Fail 'transition: quality no refiere el bundle vigente'}};$occurred=[DateTimeOffset]::Now.ToString('O',[Globalization.CultureInfo]::InvariantCulture);$max=0;foreach($e in $baseline.History.Events){if($e.id-match'^(?:TRN|MIG)-([0-9]+)$'){$n=[int]$Matches[1];if($n-gt$max){$max=$n}}};$id='TRN-'+($max+1).ToString('000');$gates=@();if($Destination-in$workflow.SpecIn){$gates+='approvals.specification'};if($Destination-in$workflow.PubIn){$gates+='approvals.publication'};if($workflow.ArchEnabled-and$Destination-in$workflow.ArchIn){$gates+='approvals.architecture'};$historyPath=Join-Path $Root 'progress/history.yaml';$featuresPath=Join-Path $Root 'features.yaml';$progressPath=Join-Path $Root 'progress/current.yaml';$before=@{};$after=@{};foreach($p in @($historyPath,$featuresPath,$progressPath)){$before[$p]=[IO.File]::ReadAllBytes($p)};$after[$historyPath]=[Text.UTF8Encoding]::new($false).GetBytes((Append-Transition ([IO.File]::ReadAllText($historyPath)) $id $baseline.Active $baseline.Phase $Destination $occurred $ActorValue $ReferenceValue $gates));$after[$featuresPath]=[Text.UTF8Encoding]::new($false).GetBytes((Replace-ActiveStatus ([IO.File]::ReadAllText($featuresPath)) $baseline.Active $Destination));$after[$progressPath]=[Text.UTF8Encoding]::new($false).GetBytes((Replace-Phase ([IO.File]::ReadAllText($progressPath)) $Destination));$stage=Get-StagingPath $Root;$journal=Get-JournalPath $Root;New-Item -ItemType Directory -Path $stage -Force|Out-Null;try{$targets=[Collections.Generic.List[object]]::new();foreach($p in @($historyPath,$featuresPath,$progressPath)){$name=[IO.Path]::GetFileName($p);Write-Bytes (Join-Path $stage "$name.before") $before[$p];Write-Bytes (Join-Path $stage "$name.after") $after[$p];$beforeHash=Get-Hash $p;$afterHash=Get-Hash (Join-Path $stage "$name.after");if((Get-Hash (Join-Path $stage "$name.before"))-ne$beforeHash){Fail "staging before inconsistente para $name"};[void]$targets.Add([ordered]@{path=(Get-RelativePath $Root $p).Replace('\','/');before_sha256=$beforeHash;after_sha256=$afterHash})};$journalText="schema: 1`ncreated_at: $(Quote-Yaml $occurred)`nroot: '.'`nevent:`n  id: $id`n  feature: $(Quote-Yaml $baseline.Active)`n  from: $(Quote-Yaml $baseline.Phase)`n  to: $(Quote-Yaml $Destination)`ntargets:`n";foreach($t in $targets){$journalText+="  - path: $(Quote-Yaml $t.path)`n    before_sha256: $(Quote-Yaml $t.before_sha256)`n    after_sha256: $(Quote-Yaml $t.after_sha256)`n"};Write-Bytes $journal ([Text.UTF8Encoding]::new($false).GetBytes($journalText));foreach($p in @($historyPath,$featuresPath,$progressPath)){$name=[IO.Path]::GetFileName($p);Copy-Item -LiteralPath (Join-Path $stage "$name.after") -Destination $p -Force};$check=Validate-State $Root $workflow $true;if($check.Phase-ne$Destination){Fail 'validación interna: destino no aplicado'};Remove-Item -LiteralPath $stage -Recurse -Force;Remove-Item -LiteralPath $journal -Force;Write-Host "TRANSITIONED: $($baseline.Phase) → $Destination ($id)"}catch{throw}}
function Validate-Harness([string]$Root,[bool]$TemplateMode){if(-not(Test-Path -LiteralPath $Root -PathType Container)){Fail "No existe la raíz del harness: $Root"};foreach($r in @('AGENTS.md','.harness/README.md','.harness/VERSION','.harness/workflow.yaml','.harness/project.yaml','features.yaml','progress/current.yaml','docs/architecture.md','docs/decisions.md','docs/conventions.md','docs/security.md')){if(-not(Test-Path -LiteralPath (Join-Path $Root $r) -PathType Leaf)){Fail "Falta $r"}};Check-Markers $Root $TemplateMode;Assert-NoRecovery $Root $false;$workflow=Read-Workflow $Root;$script:Warnings|ForEach-Object{Write-Warning $_};$script:Warnings.Clear();$null=Validate-State $Root $workflow;if($null-eq$workflow.PhaseRules){Write-Warning 'validation.phase_rules no está configurado; el control adicional de archivos por fase está inactivo.'};if(-not$workflow.ArchEnabled){Write-Warning 'La validación automática de arquitectura está inactiva; la revisión humana según impacto sigue vigente.'};if(-not(Test-Path -LiteralPath (Join-Path $Root '.git'))){Write-Warning 'El destino todavía no es un repositorio Git.'};Write-Host "VALID: harness consistente en $Root"}
function Get-HarnessVersion([string]$Root){$p=Join-Path $Root '.harness/VERSION';if(-not(Test-Path -LiteralPath $p -PathType Leaf)){Fail "No se encontró .harness/VERSION en $Root"};(Get-Content -Raw $p).Trim()}
function Validate-ManagedManifest([string]$Root){$path=Join-Path $Root '.harness/managed-files.txt';if(-not(Test-Path -LiteralPath $path -PathType Leaf)){return};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);foreach($line in @(Get-Content -LiteralPath $path)){$entry=$line.Trim();if([string]::IsNullOrWhiteSpace($entry)){continue};if($entry.Contains('\')-or$entry.Contains(':')-or$entry.StartsWith('/')-or$entry-match'(^|/)\.($|/)'-or$entry-match'(^|/)\.\.($|/)'-or$entry-match'(^|/)//|/$'){Fail "Ruta insegura en manifiesto: '$entry'"};if(-not$seen.Add($entry)){Fail "Ruta duplicada en manifiesto: '$entry'"}}}
function Initialize-Project([string]$Root,[string]$Name){if([string]::IsNullOrWhiteSpace($Name)-or$Name-match'[\x00-\x1F\x7F]'-or$Name.Contains('{{PROJECT_NAME}}')-or$Name.Contains('{{DATE}}')){Fail 'ProjectName es obligatorio y no puede contener controles ni marcadores reservados.'};Validate-ManagedManifest $Root;$files=@('AGENTS.md','.harness/README.md','.harness/project.yaml','.harness/workflow.yaml','features.yaml','progress/current.yaml','docs/architecture.md');$date=Get-Date -Format 'yyyy-MM-dd';$yamlName=$Name.Replace('\','\\').Replace('"','\"');$changed=0;foreach($r in $files){$p=Join-Path $Root $r;if(-not(Test-Path -LiteralPath $p -PathType Leaf)){Fail "Falta archivo inicializable: $r"};$old=Get-Content -Raw $p;$replacement=if($r-match'\.(yaml|yml)$'){$yamlName}else{$Name};$new=$old.Replace('{{PROJECT_NAME}}',$replacement).Replace('{{DATE}}',$date);if($new-ne$old){[IO.File]::WriteAllText($p,$new,[Text.UTF8Encoding]::new($false));$changed++}};Write-Host "Harness inicializado para '$Name' en $Root ($changed archivo(s))."}
# INC-05 extension point
function Trace-Fail([string]$Code,[string]$Path,[int]$Line,[string]$Id,[string]$Reason) { throw ("{0}: {1} línea {2}{3}: {4}" -f $Code,$Path,$Line,($(if([string]::IsNullOrWhiteSpace($Id)){''}else{" ID $Id"})),$Reason) }
function Read-TraceLines([string]$Path) {
    try { $bytes=[IO.File]::ReadAllBytes($Path) } catch { Trace-Fail 'INPUT_PATH_UNSAFE' $Path 0 '' 'no se pudo leer el archivo' }
    if ($bytes.Length -gt 1048576) { Trace-Fail 'INPUT_MARKDOWN_INVALID' $Path 0 '' 'supera 1 MiB' }
    try { $text=[Text.UTF8Encoding]::new($false,$true).GetString($bytes) } catch { Trace-Fail 'INPUT_MARKDOWN_INVALID' $Path 0 '' 'UTF-8 inválido' }
    if ($text.StartsWith([char]0xFEFF)) { $text=$text.Substring(1) }
    for($i=0;$i -lt $text.Length;$i++){if($text[$i] -eq [char]13 -and ($i+1 -ge $text.Length -or $text[$i+1] -ne [char]10)){Trace-Fail 'INPUT_MARKDOWN_INVALID' $Path 0 '' 'fin de línea CR aislado'}}
    $out=[Collections.Generic.List[object]]::new();$fence=$null;$lineNo=0
    foreach($raw in ($text -split "`n")) { $lineNo++;$line=$raw.TrimEnd("`r")
        if ($null -ne $fence) { if ($line -match ('^ {0,3}'+[regex]::Escape($fence.Char)+"{"+$fence.Count+',} *$')) { $fence=$null }; continue }
        if ($line -match '^ {0,3}(`{3,}|~{3,})(.*)$') { $mark=$Matches[1];$info=$Matches[2];$char=$mark.Substring(0,1);if($char -eq '`' -and $info.Contains('`')){Trace-Fail 'INPUT_MARKDOWN_INVALID' $Path $lineNo '' 'información de fence inválida'};$fence=[pscustomobject]@{Char=$char;Count=$mark.Length};continue }
        [void]$out.Add([pscustomobject]@{Line=$lineNo;Text=$line})
    }
    if ($null -ne $fence) { Trace-Fail 'INPUT_MARKDOWN_INVALID' $Path $lineNo '' 'fence sin cierre' }
    return @($out)
}
function Trace-Cells([string]$Text,[string]$Path,[int]$Line,[int]$Columns) { if(-not($Text.StartsWith('|') -and $Text.EndsWith('|'))){Trace-Fail 'TRACE_DEFINITION_FORMAT' $Path $Line '' 'fila debe iniciar y terminar con |'};$cells=$Text.Substring(1,$Text.Length-2).Split('|');if($cells.Count -ne $Columns){Trace-Fail 'TRACE_DEFINITION_FORMAT' $Path $Line '' "se esperaban $Columns columnas"};return @($cells|ForEach-Object{$_.Trim(' ')}) }
function Trace-RefTokens([string]$Text,[string]$Path,[int]$Line,[string]$Id) {
    if([string]::IsNullOrWhiteSpace($Text)){Trace-Fail 'TRACE_REFERENCE_FORMAT' $Path $Line $Id 'lista vacía'};if($Text -match '[*…]|\.\.|(?<![A-Za-z0-9])\d+\s*-\s*\d+(?![A-Za-z0-9])|\|'){Trace-Fail 'TRACE_REFERENCE_FORMAT' $Path $Line $Id 'rango, comodín o separador no permitido'}
    $parts=($Text -replace '\s+/\s+', ', ' -replace '\s+y\s+', ', ') -split ', ';$refs=[Collections.Generic.List[string]]::new();foreach($part in $parts){$token=$part.Trim().TrimEnd('.',';');if($token.StartsWith('[')-and$token.EndsWith(']')){$token=$token.Substring(1,$token.Length-2)};if($token -notmatch '^(?:(feat-[0-9]{3,})/)?(REQ|NFR|AC|TASK|TEST|RUN|MAN)-[0-9]{3,}$'){Trace-Fail 'TRACE_REFERENCE_FORMAT' $Path $Line $Id "referencia inválida '$token'"};[void]$refs.Add($token)};return @($refs)
}
function Add-TraceDef($Defs,[string]$Type,[string]$Id,[string]$Path,[int]$Line,[bool]$Closed=$false) { if($Id -notmatch ('^'+$Type+'-[0-9]{3,}$')){Trace-Fail 'TRACE_DEFINITION_FORMAT' $Path $Line $Id 'ID mal formado'};if($Defs.Contains($Id)){Trace-Fail 'TRACE_DEFINITION_DUPLICATE' $Path $Line $Id 'definición repetida'};$Defs[$Id]=[pscustomobject]@{Type=$Type;Id=$Id;Path=$Path;Line=$Line;Closed=$Closed;Refs=[Collections.Generic.List[string]]::new()} }
function Add-TraceRefs($Defs,[string]$From,[string]$Text,[string]$Path,[int]$Line) { $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($ref in @(Trace-RefTokens $Text $Path $Line $From)){if(-not$seen.Add($ref)){Trace-Fail 'TRACE_REFERENCE_FORMAT' $Path $Line $From 'referencia repetida en la misma lista'};if(-not $Defs[$From].Refs.Contains($ref)){[void]$Defs[$From].Refs.Add($ref)}} }
function Parse-TraceContract([string]$Root,[string]$Active) {
    $dir=Join-Path $Root "specs/features/$Active";$all=[ordered]@{};foreach($t in @('REQ','NFR','AC','TASK','TEST','RUN','MAN')){$all[$t]=[ordered]@{}};$summaries=[ordered]@{Tests=[ordered]@{};ACs=[ordered]@{}}
    $fileNames=@('requirements.md','acceptance.md','tasks.md','test-plan.md','evidence.md')
    foreach($name in $fileNames){$path=Join-Path $dir $name;if(-not(Test-Path -LiteralPath $path -PathType Leaf)){Trace-Fail 'TRACE_DEFINITION_FORMAT' $name 0 '' 'artefacto canónico ausente'};$lines=Read-TraceLines $path;$currentAc='';$inNfr=$false;$inScenarios=$false;$inExec=$false;$inManual=$false;$inTestSummary=$false;$inAcSummary=$false
        foreach($item in $lines){$line=$item.Line;$s=$item.Text
            if($name -eq 'requirements.md'){if($s -match '^#{2,3} (REQ-[0-9]{3,})\b'){$currentReq=$Matches[1];Add-TraceDef $all.REQ 'REQ' $currentReq $name $line};if($s -match '^Evidencia:\s*(.+)$' -and -not [string]::IsNullOrWhiteSpace($currentReq)){Add-TraceRefs $all.REQ $currentReq $Matches[1] $name $line};if($s -eq '## Requisitos no funcionales'){$inNfr=$true};if($inNfr -and $s.StartsWith('| NFR-')){$c=Trace-Cells $s $name $line 4;Add-TraceDef $all.NFR 'NFR' $c[0] $name $line;Add-TraceRefs $all.NFR $c[0] $c[3] $name $line}}
            elseif($name -eq 'acceptance.md'){if($s -match '^## (AC-[0-9]{3,})\b'){$currentAc=$Matches[1];Add-TraceDef $all.AC 'AC' $currentAc $name $line};foreach($field in @('Requisitos','Tareas','Pruebas')){if($s -match ('^- '+$field+':\s*(.+)$')){if(-not $all.AC.Contains($currentAc)){Trace-Fail 'TRACE_DEFINITION_FORMAT' $name $line '' "campo $field fuera de AC"};Add-TraceRefs $all.AC $currentAc $Matches[1] $name $line}}
                if($s -match '^\| (AC-[0-9]{3,}) \|'){$c=Trace-Cells $s $name $line 6;if(-not $all.AC.Contains($c[0])){Trace-Fail 'TRACE_REFERENCE_MISSING' $name $line $c[0] 'AC no definida'};Add-TraceRefs $all.AC $c[0] $c[1] $name $line;Add-TraceRefs $all.AC $c[0] $c[2] $name $line;Add-TraceRefs $all.AC $c[0] $c[3] $name $line}}
            elseif($name -eq 'tasks.md'){if($s -match '^- \[([ x])\] (TASK-[0-9]{3,})(?:\s|$)'){$task=$Matches[2];Add-TraceDef $all.TASK 'TASK' $task $name $line ($Matches[1] -eq 'x');foreach($match in [regex]::Matches($s,'\[(REQ|NFR|AC|TEST)-[0-9]{3,}\]')){[void]$all.TASK[$task].Refs.Add($match.Value.Trim('[',']'))}}elseif($s -match '^- \[[^ xX]\] TASK-'){Trace-Fail 'TRACE_DEFINITION_FORMAT' $name $line '' 'checkbox TASK inválido'} }
            elseif($name -eq 'test-plan.md'){if($s -eq '## Escenarios'){$inScenarios=$true};if($inScenarios -and $s -match '^\| TEST-[0-9]{3,} \|'){$c=Trace-Cells $s $name $line 8;Add-TraceDef $all.TEST 'TEST' $c[0] $name $line ($c[7] -eq 'pass');foreach($ref in @(Trace-RefTokens ($c[3] -replace '`','') $name $line $c[0])){[void]$all.TEST[$c[0]].Refs.Add($ref)};foreach($ref in @(Trace-RefTokens $c[4] $name $line $c[0])){[void]$all.TEST[$c[0]].Refs.Add($ref)}} }
            elseif($name -eq 'evidence.md'){if($s -eq '## Ejecuciones automatizadas'){$inExec=$true;$inManual=$false};if($s -eq '## Verificaciones manuales'){$inManual=$true;$inExec=$false};if($s -eq '## Resumen final de pruebas'){$inTestSummary=$true;$inAcSummary=$false};if($s -eq '## Resumen final de aceptación'){$inAcSummary=$true;$inTestSummary=$false};if(($inExec -or $inManual) -and $s -match '^\| (RUN|MAN)-[0-9]{3,} \|'){$c=Trace-Cells $s $name $line 11;$type=$c[0].Substring(0,3);Add-TraceDef $all[$type] $type $c[0] $name $line ($c[6] -eq 'pass');if($c[1] -notmatch '^\d{4}-\d{2}-\d{2}T'){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $name $line $c[0] 'fecha inválida'};if($c[6] -notin @('pass','fail','blocked','pending')){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $name $line $c[0] 'resultado inválido'};if($c[7] -notmatch '^(No aplica|0|-?[1-9][0-9]*)$'){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $name $line $c[0] 'Exit code inválido'};if($c[8] -ne 'No aplica' -and $c[8] -notin @('INPUT_MARKDOWN_INVALID','TRACE_FEATURE_FORMAT','TRACE_FEATURE_DUPLICATE','TRACE_FEATURE_MISSING','TRACE_FEATURE_DIRECTORY','TRACE_DEFINITION_FORMAT','TRACE_DEFINITION_DUPLICATE','TRACE_REFERENCE_FORMAT','TRACE_REFERENCE_MISSING','TRACE_COVERAGE_MISSING','EVIDENCE_EXECUTION_INVALID','EVIDENCE_SUMMARY_INVALID','EVIDENCE_REFERENCE_MISSING','CHANGE_REQUEST_REQUIRED','CHANGE_REQUEST_INVALID','CHANGE_APPROVAL_STALE','BLOCKER_REQUIRED','BLOCKER_UNEXPECTED','BLOCKER_CODE_INVALID','BLOCKER_EXPLANATION_REQUIRED','BLOCKER_REFERENCE_INVALID','ADR_ID_DUPLICATE','ADR_METADATA_INVALID','ADR_AMENDMENT_INVALID','CLOSE_TASK_OPEN','CLOSE_AC_UNVERIFIED','CLOSE_TEST_UNSATISFACTORY')){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $name $line $c[0] 'código diagnóstico desconocido'};foreach($ref in @(Trace-RefTokens $c[5] $name $line $c[0])){[void]$all[$type][$c[0]].Refs.Add($ref)}};if($inTestSummary -and $s -match '^\| TEST-[0-9]{3,} \|'){$c=Trace-Cells $s $name $line 3;$summaries.Tests[$c[0]]=$c[1..2]};if($inAcSummary -and $s -match '^\| AC-[0-9]{3,} \|'){$c=Trace-Cells $s $name $line 3;$summaries.ACs[$c[0]]=$c[1..2]}}
        }
    }
    return [pscustomobject]@{Defs=$all;Summaries=$summaries}
}
function Trace-Resolve([string]$Ref,[string]$Active,$Defs,[string]$Path,[int]$Line,[string]$From) {
    if($Ref -match '^(feat-[0-9]{3,})/(.+)$'){$feature=$Matches[1];$id=$Matches[2];$external=Join-Path $script:TraceRoot "specs/features/$feature";if(-not(Test-Path -LiteralPath $external -PathType Container)){Trace-Fail 'TRACE_REFERENCE_MISSING' $Path $Line $From "feature externa ausente '$feature'"};$file=if($id -match '^TEST-'){'test-plan.md'}elseif($id -match '^AC-'){'acceptance.md'}elseif($id -match '^TASK-'){'tasks.md'}elseif($id -match '^(REQ|NFR)-'){'requirements.md'}else{''};if([string]::IsNullOrWhiteSpace($file)-or(-not(Test-Path -LiteralPath (Join-Path $external $file) -PathType Leaf))){Trace-Fail 'TRACE_REFERENCE_MISSING' $Path $Line $From "referencia externa no resoluble '$Ref'"};if(-not((Get-Content -Raw (Join-Path $external $file)) -match [regex]::Escape($id))){Trace-Fail 'TRACE_REFERENCE_MISSING' $Path $Line $From "referencia externa no resoluble '$Ref'"};return}
    $kind=([regex]::Match($Ref,'^(REQ|NFR|AC|TASK|TEST|RUN|MAN)-')).Groups[1].Value;if([string]::IsNullOrWhiteSpace($kind)-or-not $Defs.Contains($kind)-or-not $Defs[$kind].Contains($Ref)){Trace-Fail 'TRACE_REFERENCE_MISSING' $Path $Line $From "referencia local no resoluble '$Ref'"}
}
function Validate-TraceRefs($Contract,[string]$Root,[string]$Active) {
    $script:TraceRoot=$Root;$defs=$Contract.Defs
    foreach($type in $defs.Keys){foreach($def in $defs[$type].Values){$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($ref in $def.Refs){if(-not$seen.Add($ref)){Trace-Fail 'TRACE_REFERENCE_FORMAT' $def.Path $def.Line $def.Id 'referencia repetida'};Trace-Resolve $ref $Active $defs $def.Path $def.Line $def.Id}}}
    foreach($ac in $defs.AC.Values){foreach($kind in @('REQ','NFR')){foreach($ref in @($ac.Refs|Where-Object{$_ -match ('^'+$kind+'-')})){if($defs[$kind].Contains($ref)-and-not $defs[$kind][$ref].Refs.Contains($ac.Id)){[void]$defs[$kind][$ref].Refs.Add($ac.Id)}}}}
    foreach($type in @('REQ','NFR')){foreach($def in $defs[$type].Values){if(-not(@($def.Refs|Where-Object{$_ -match '^(?:feat-[0-9]{3,}/)?AC-'}).Count -gt 0)){Trace-Fail 'TRACE_COVERAGE_MISSING' $def.Path $def.Line $def.Id 'REQ/NFR no tiene AC'}}}
    foreach($def in $defs.AC.Values){if(-not(@($def.Refs|Where-Object{$_ -match '^(?:feat-[0-9]{3,}/)?(REQ|NFR)-'}).Count -gt 0)){Trace-Fail 'TRACE_COVERAGE_MISSING' $def.Path $def.Line $def.Id 'AC sin REQ/NFR'};foreach($kind in @('TASK','TEST')){if(-not(@($def.Refs|Where-Object{$_ -match ('^(?:feat-[0-9]{3,}/)?'+$kind+'-')}).Count -gt 0)){Trace-Fail 'TRACE_COVERAGE_MISSING' $def.Path $def.Line $def.Id "AC sin $kind"}}}
    foreach($def in $defs.TASK.Values){if(-not(@($def.Refs|Where-Object{$_ -match '^(?:feat-[0-9]{3,}/)?(REQ|NFR)-'}).Count -gt 0)){Trace-Fail 'TRACE_COVERAGE_MISSING' $def.Path $def.Line $def.Id 'TASK sin REQ/NFR'};foreach($kind in @('AC','TEST')){if(-not(@($def.Refs|Where-Object{$_ -match ('^(?:feat-[0-9]{3,}/)?'+$kind+'-')}).Count -gt 0)){Trace-Fail 'TRACE_COVERAGE_MISSING' $def.Path $def.Line $def.Id "TASK sin $kind"}}}
    foreach($def in $defs.TEST.Values){foreach($kind in @('AC','TASK')){if(-not(@($def.Refs|Where-Object{$_ -match ('^(?:feat-[0-9]{3,}/)?'+$kind+'-')}).Count -gt 0)){Trace-Fail 'TRACE_COVERAGE_MISSING' $def.Path $def.Line $def.Id "TEST sin $kind"}}}
}
function Validate-TraceEvidence($Contract,[string]$Root,[string]$Active,[string]$Phase) {
    $defs=$Contract.Defs;$evidence=(Join-Path $Root "specs/features/$Active/evidence.md");$testIds=@($defs.TEST.Keys);$acIds=@($defs.AC.Keys)
    if($Phase -in @('verification','publication_review','done')){
        if($Contract.Summaries.Tests.Count -ne $testIds.Count){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' 'evidence.md' 0 '' 'debe existir una fila por TEST local'};if($Contract.Summaries.ACs.Count -ne $acIds.Count){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' 'evidence.md' 0 '' 'debe existir una fila por AC local'}
        foreach($id in $testIds){if(-not$Contract.Summaries.Tests.Contains($id)){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' 'evidence.md' 0 $id 'TEST ausente en resumen'};$row=$Contract.Summaries.Tests[$id];if($row[1] -cne 'pass'){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' 'evidence.md' 0 $id 'TEST no está en pass'};$run=$row[0];if(-not($defs.RUN.Contains($run)-or$defs.MAN.Contains($run))){Trace-Fail 'EVIDENCE_REFERENCE_MISSING' 'evidence.md' 0 $id "ejecución ausente '$run'"};$exec=if($defs.RUN.Contains($run)){$defs.RUN[$run]}else{$defs.MAN[$run]};if(-not$exec.Closed -or $exec.Refs -notcontains $id){Trace-Fail 'EVIDENCE_REFERENCE_MISSING' 'evidence.md' $exec.Line $id 'ejecución no declara TEST seleccionado'}}
        foreach($id in $acIds){if(-not$Contract.Summaries.ACs.Contains($id)){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' 'evidence.md' 0 $id 'AC ausente en resumen'};$row=$Contract.Summaries.ACs[$id];if($row[1] -cne 'pass'){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' 'evidence.md' 0 $id 'AC no está en pass'};$run=$row[0];if(-not($defs.RUN.Contains($run)-or$defs.MAN.Contains($run))){Trace-Fail 'EVIDENCE_REFERENCE_MISSING' 'evidence.md' 0 $id "ejecución ausente '$run'"};$exec=if($defs.RUN.Contains($run)){$defs.RUN[$run]}else{$defs.MAN[$run]};if(-not$exec.Closed -or $exec.Refs -notcontains $id){Trace-Fail 'EVIDENCE_REFERENCE_MISSING' 'evidence.md' $exec.Line $id 'ejecución no declara AC seleccionado'}}
    }
}
function Validate-FeatureInventory([string]$Root,$Result) {
    $features=$Result.Features;$featureIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($id in $features.Keys){if($id -notmatch '^feat-[0-9]{3,}$'){Trace-Fail 'TRACE_FEATURE_FORMAT' 'features.yaml' 0 $id 'ID de feature inválido'};if(-not$featureIds.Add($id)){Trace-Fail 'TRACE_FEATURE_DUPLICATE' 'features.yaml' 0 $id 'feature repetida'}}
    $progress=$Result.Progress;$active=[string]$progress.active_feature;if(-not$featureIds.Contains($active)){Trace-Fail 'TRACE_FEATURE_MISSING' 'progress/current.yaml' 0 'active_feature' "feature ausente '$active'"};foreach($entry in $features.Values){foreach($dep in @($entry.depends_on)){if(-not$featureIds.Contains([string]$dep)){Trace-Fail 'TRACE_FEATURE_MISSING' 'features.yaml' 0 ([string]$entry.id) "dependencia ausente '$dep'"}}}
    $specRoot=Join-Path $Root 'specs/features';$dirs=@(Get-ChildItem -LiteralPath $specRoot -Directory -Force -ErrorAction SilentlyContinue|ForEach-Object{$_.Name});foreach($dir in $dirs){if($dir -notmatch '^feat-[0-9]{3,}$' -or -not$featureIds.Contains($dir)){Trace-Fail 'TRACE_FEATURE_DIRECTORY' 'specs/features' 0 $dir 'directorio no listado'}};foreach($id in $featureIds){$status=[string]$features[$id].status;if($status -in @('specification','spec_review','approved','implementation','verification','publication_review','done') -and $id -ne $Result.Active -and -not(Test-Path -LiteralPath (Join-Path $specRoot $id) -PathType Container)){Trace-Fail 'TRACE_FEATURE_DIRECTORY' 'specs/features' 0 $id 'directorio requerido ausente'}}
}
function Validate-Blockers([string]$Root,$Workflow,$Result) {
    $value=$Result.Progress.blockers;if($null -eq $value){$value=@()};$items=@($value);if($Result.Phase -eq 'blocked' -and $items.Count -eq 0){Trace-Fail 'BLOCKER_REQUIRED' 'progress/current.yaml' 0 'blockers' 'blocked requiere al menos un blocker'};if($Result.Phase -ne 'blocked' -and $items.Count -gt 0){Trace-Fail 'BLOCKER_UNEXPECTED' 'progress/current.yaml' 0 'blockers' 'blockers solo se permiten en blocked'};foreach($item in $items){if($item -isnot [Collections.IDictionary]){Trace-Fail 'BLOCKER_REQUIRED' 'progress/current.yaml' 0 'blockers' 'cada blocker debe ser objeto'};$code=[string]$item.code;if($code -notin $Workflow.BlockingCodes){Trace-Fail 'BLOCKER_CODE_INVALID' 'progress/current.yaml' 0 'blockers' "código '$code' no está en catálogo"};if([string]::IsNullOrWhiteSpace([string]$item.explanation)){Trace-Fail 'BLOCKER_EXPLANATION_REQUIRED' 'progress/current.yaml' 0 'blockers' 'explanation es obligatorio'};if($item.Contains('references')){foreach($ref in @($item.references)){if([string]$ref -notmatch '^(?:(feat-[0-9]{3,})/)?(REQ|NFR|AC|TASK|TEST)-[0-9]{3,}$'){Trace-Fail 'BLOCKER_REFERENCE_INVALID' 'progress/current.yaml' 0 'blockers' "referencia inválida '$ref'"}}}}
}
function Validate-ADRs([string]$Root,$Workflow) {
    $path=Join-Path $Root 'docs/decisions.md';$lines=Read-TraceLines $path;$ids=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$baseIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($item in $lines){if($item.Text -match '^## (ADR-[0-9]{3,})(?:-AMEND-[0-9]{3,})?\b'){$id=$Matches[1];if(-not$ids.Add($id)){Trace-Fail 'ADR_ID_DUPLICATE' 'docs/decisions.md' $item.Line $id 'ADR repetido'};$baseIds.Add($id)|Out-Null}}
    foreach($id in $ids){if($id -notin $Workflow.LegacyIds){$text=Get-Content -Raw $path;if($text -notmatch ('(?ms)^## '+[regex]::Escape($id)+'.*?^- \*\*Estado:\*\*')){Trace-Fail 'ADR_METADATA_INVALID' 'docs/decisions.md' 0 $id 'falta Estado canónico'};if($text -notmatch ('(?ms)^## '+[regex]::Escape($id)+'.*?^- \*\*Decisor:\*\*')){Trace-Fail 'ADR_METADATA_INVALID' 'docs/decisions.md' 0 $id 'falta Decisor canónico'};if($text -notmatch ('(?ms)^## '+[regex]::Escape($id)+'.*?^- \*\*Referencia de aprobación:\*\*')){Trace-Fail 'ADR_METADATA_INVALID' 'docs/decisions.md' 0 $id 'falta Referencia de aprobación canónica'}}}
}
function Invoke-TraceValidation([string]$Root,$Workflow,$Result) {
    Validate-FeatureInventory $Root $Result;Validate-Blockers $Root $Workflow $Result;Validate-ADRs $Root $Workflow
    if($Result.Phase -in @('spec_review','approved','implementation','verification','publication_review','done') -and (Test-Path -LiteralPath (Join-Path $Root "specs/features/$($Result.Active)/evidence.md") -PathType Leaf)){$contract=Parse-TraceContract $Root $Result.Active;Validate-TraceRefs $contract $Root $Result.Active;Validate-TraceEvidence $contract $Root $Result.Active $Result.Phase;if($Result.Phase -in @('verification','publication_review','done')){foreach($task in $contract.Defs.TASK.Values){if(-not$task.Closed){Trace-Fail 'CLOSE_TASK_OPEN' $task.Path $task.Line $task.Id 'TASK abierta'}}}}
}
$script:Inc05BaseValidateState=${function:Validate-State}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){$result=& $script:Inc05BaseValidateState $Root $Workflow $SkipJournal;Invoke-TraceValidation $Root $Workflow $result;return $result}
function Validate-ChangeRequest([string]$Root,$Active,[string]$ChangeId,[string]$ReferenceValue,[string]$From,[string]$To,[string]$ExpectedOrigin) {
    $expected="specs/features/$Active/change-requests/$ChangeId.md";if($ReferenceValue -cne $expected){Trace-Fail 'CHANGE_REQUEST_INVALID' 'transition' 0 $ChangeId "-Reference debe ser '$expected'"};$path=Join-Path $Root $expected;if(-not(Test-Path -LiteralPath $path -PathType Leaf)){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'CR ausente'};$text=Get-Content -Raw -LiteralPath $path;$heading=[regex]::Matches($text,'(?m)^# Change request — (CR-[0-9]{3,})\s*$');if($heading.Count -ne 1 -or $heading[0].Groups[1].Value -cne $ChangeId){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 1 $ChangeId 'heading/ID no coinciden'};foreach($field in @('ID','Feature','Estado','Digest de origen','Digest objetivo','Autor','Creada en','Motivo','Trabajo detenido','Impacto arquitectónico','Impacto de publicación','Decidido por','Decidido en','Referencia de decisión','Aprobaciones a renovar')){if($text -notmatch ('(?m)^- '+[regex]::Escape($field)+':\s*([^\r\n]+)$')){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId "falta campo '$field'"}}
    $state=([regex]::Match($text,'(?m)^- Estado:\s*([^\r\n]+)$')).Groups[1].Value.Trim();if($To -eq 'specification' -and $state -cne 'approved_for_return'){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId "Estado '$state' no habilita retorno"};if($To -eq 'spec_review' -and $state -cne 'under_review'){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'spec_review requiere under_review'};if($To -eq 'approved' -and $state -cne 'closed'){Trace-Fail 'CHANGE_APPROVAL_STALE' $expected 0 $ChangeId 'approved requiere CR closed'}
    return $path
}
function Replace-ProgressBlocker([string]$Text,[string]$Code,[string]$Explanation,[string[]]$References){$refs=if($References.Count -eq 0){'[]'}else{'['+(($References|ForEach-Object{Quote-Yaml $_}) -join ', ')+']'};$block="blockers:`n  - code: $(Quote-Yaml $Code)`n    explanation: $(Quote-Yaml $Explanation)`n    references: $refs";$new=[regex]::Replace($Text,'(?ms)^blockers:\s*\[\].*?(?=^risks:)',($block+"`n"),1);if($new -eq $Text){$new=[regex]::Replace($Text,'(?ms)^blockers:\s*.*?(?=^risks:)',($block+"`n"),1)};if($new -eq $Text){Fail 'BLOCKER_REQUIRED: no se pudo preparar blockers'};return $new}
function Transition-WithBlocker([string]$Root,$Destination,$ActorValue,$ReferenceValue,$BlockerCodeValue,$BlockerExplanationValue,[string[]]$BlockerReferences) {
    $workflow=Read-Workflow $Root;$baseline=& $script:Inc05BaseValidateState $Root $workflow $false;if($Destination -ne 'blocked'){Trace-Fail 'BLOCKER_UNEXPECTED' 'transition' 0 'Blocker*' 'argumentos solo válidos hacia blocked'};if([string]::IsNullOrWhiteSpace($BlockerCodeValue)){Trace-Fail 'BLOCKER_REQUIRED' 'transition' 0 'BlockerCode' 'code obligatorio'};if($BlockerCodeValue -notin $workflow.BlockingCodes){Trace-Fail 'BLOCKER_CODE_INVALID' 'transition' 0 'BlockerCode' 'código fuera del catálogo'};if([string]::IsNullOrWhiteSpace($BlockerExplanationValue)){Trace-Fail 'BLOCKER_EXPLANATION_REQUIRED' 'transition' 0 'BlockerExplanation' 'explanation obligatoria'};$refs=[Collections.Generic.List[string]]::new();foreach($raw in @($BlockerReferences)){foreach($ref in ($raw -split ',')){if(-not[string]::IsNullOrWhiteSpace($ref)){[void]$refs.Add($ref.Trim())}}};foreach($ref in $refs){if($ref -notmatch '^(?:(feat-[0-9]{3,})/)?(REQ|NFR|AC|TASK|TEST)-[0-9]{3,}$'){Trace-Fail 'BLOCKER_REFERENCE_INVALID' 'transition' 0 'BlockerReference' "referencia inválida '$ref'"}}
    $occurred=[DateTimeOffset]::Now.ToString('O',[Globalization.CultureInfo]::InvariantCulture);$max=0;foreach($e in $baseline.History.Events){if($e.id-match'^(?:TRN|MIG)-([0-9]+)$'){$n=[int]$Matches[1];if($n -gt $max){$max=$n}}};$id='TRN-'+($max+1).ToString('000');$historyPath=Join-Path $Root 'progress/history.yaml';$featuresPath=Join-Path $Root 'features.yaml';$progressPath=Join-Path $Root 'progress/current.yaml';$paths=@($historyPath,$featuresPath,$progressPath);$before=@{};$after=@{};foreach($p in $paths){$before[$p]=[IO.File]::ReadAllBytes($p)};$gates=@();$after[$historyPath]=[Text.UTF8Encoding]::new($false).GetBytes((Append-Transition ([IO.File]::ReadAllText($historyPath)) $id $baseline.Active $baseline.Phase 'blocked' $occurred $ActorValue $ReferenceValue $gates));$after[$featuresPath]=[Text.UTF8Encoding]::new($false).GetBytes((Replace-ActiveStatus ([IO.File]::ReadAllText($featuresPath)) $baseline.Active 'blocked'));$after[$progressPath]=[Text.UTF8Encoding]::new($false).GetBytes((Replace-ProgressBlocker ([IO.File]::ReadAllText($progressPath)) $BlockerCodeValue $BlockerExplanationValue @($refs)));$stage=Get-StagingPath $Root;$journal=Get-JournalPath $Root;New-Item -ItemType Directory -Path $stage -Force|Out-Null;try{$targets=[Collections.Generic.List[object]]::new();foreach($p in $paths){$name=[IO.Path]::GetFileName($p);Write-Bytes (Join-Path $stage "$name.before") $before[$p];Write-Bytes (Join-Path $stage "$name.after") $after[$p];$h=Get-Hash $p;if((Get-Hash (Join-Path $stage "$name.before")) -cne $h){Fail "staging before inconsistente para $name"};[void]$targets.Add([ordered]@{path=(Get-RelativePath $Root $p).Replace('\','/');before_sha256=$h;after_sha256=Get-Hash (Join-Path $stage "$name.after")})};$journalText="schema: 1`ncreated_at: $(Quote-Yaml $occurred)`nroot: '.'`nevent:`n  id: $id`n  feature: $(Quote-Yaml $baseline.Active)`n  from: $(Quote-Yaml $baseline.Phase)`n  to: 'blocked'`ntargets:`n";foreach($t in $targets){$journalText+="  - path: $(Quote-Yaml $t.path)`n    before_sha256: $(Quote-Yaml $t.before_sha256)`n    after_sha256: $(Quote-Yaml $t.after_sha256)`n"};Write-Bytes $journal ([Text.UTF8Encoding]::new($false).GetBytes($journalText));foreach($p in $paths){$name=[IO.Path]::GetFileName($p);Copy-Item (Join-Path $stage "$name.after") $p -Force};$check=& $script:Inc05BaseValidateState $Root $workflow $true;if($check.Phase -ne 'blocked'){Fail 'validación interna: blocked no aplicado'};Remove-Item $stage -Recurse -Force;Remove-Item $journal -Force;Write-Host "TRANSITIONED: $($baseline.Phase) → blocked ($id)"}catch{throw}
}
$script:Inc05BaseTransition=${function:Transition}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){$change=$ChangeRequest;$code=$BlockerCode;$explanation=$BlockerExplanation;$refs=$BlockerReference;if($Destination -eq 'blocked'){if(-not[string]::IsNullOrWhiteSpace($change)){Trace-Fail 'CHANGE_REQUEST_REQUIRED' 'transition' 0 $change 'CR no aplica a blocked'};return Transition-WithBlocker $Root $Destination $ActorValue $ReferenceValue $code $explanation $refs};if(-not[string]::IsNullOrWhiteSpace($code)-or-not[string]::IsNullOrWhiteSpace($explanation)-or@($refs).Count -gt 0){Trace-Fail 'BLOCKER_UNEXPECTED' 'transition' 0 'Blocker*' 'argumentos fuera de blocked'};$workflow=Read-Workflow $Root;$baseline=& $script:Inc05BaseValidateState $Root $workflow $false;$governed=@('approved','implementation','verification','publication_review');if($Destination -eq 'specification' -and $baseline.Phase -in $governed){if([string]::IsNullOrWhiteSpace($change)){Trace-Fail 'CHANGE_REQUEST_REQUIRED' 'transition' 0 'ChangeRequest' 'retorno requiere CR'};Validate-ChangeRequest $Root $baseline.Active $change $ReferenceValue $baseline.Phase $Destination|Out-Null}elseif(-not[string]::IsNullOrWhiteSpace($change)){Trace-Fail 'CHANGE_REQUEST_REQUIRED' 'transition' 0 $change 'CR usada en arista no gobernada'};& $script:Inc05BaseTransition $Root $Destination $ActorValue $ReferenceValue}
$script:Inc05CurrentTransition=${function:Transition}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){$workflow=Read-Workflow $Root;$baseline=& $script:Inc05BaseValidateState $Root $workflow $false;if($Destination -in @('verification','publication_review','done')){$prospective=[pscustomobject]@{Progress=$baseline.Progress;Features=$baseline.Features;History=$baseline.History;Active=$baseline.Active;Phase=$Destination};Invoke-TraceValidation $Root $workflow $prospective};& $script:Inc05CurrentTransition $Root $Destination $ActorValue $ReferenceValue}
$script:Inc05PreflightTransition=${function:Transition}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){if($Destination -in @('verification','publication_review','done')){$taskPath=Join-Path $Root "specs/features/$((Read-Yaml (Join-Path $Root 'progress/current.yaml')).active_feature)/tasks.md";if(Test-Path -LiteralPath $taskPath -PathType Leaf){$lineNo=0;foreach($line in Get-Content -LiteralPath $taskPath){$lineNo++;if($line -match '^- \[ \] (TASK-[0-9]{3,})\b'){Trace-Fail 'CLOSE_TASK_OPEN' 'tasks.md' $lineNo $Matches[1] 'TASK abierta'}}}};& $script:Inc05PreflightTransition $Root $Destination $ActorValue $ReferenceValue}
$script:Inc05BaseReplaceProgressBlocker=${function:Replace-ProgressBlocker}
function Replace-ProgressBlocker([string]$Text,[string]$Code,[string]$Explanation,[string[]]$References){$withBlock=& $script:Inc05BaseReplaceProgressBlocker $Text $Code $Explanation $References;return (Replace-Phase $withBlock 'blocked')}
$script:Inc05BaseValidateADRs=${function:Validate-ADRs}
function Validate-ADRs([string]$Root,$Workflow) {
    $path=Join-Path $Root 'docs/decisions.md';$lines=Read-TraceLines $path;$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$headings=[Collections.Generic.List[object]]::new();foreach($item in $lines){if($item.Text -match '^## (ADR-[0-9]{3,}(?:-AMEND-[0-9]{3,})?)\b'){if(-not$seen.Add($Matches[1])){Trace-Fail 'ADR_ID_DUPLICATE' $path $item.Line $Matches[1] 'ADR repetido'};[void]$headings.Add([pscustomobject]@{Id=$Matches[1];Line=$item.Line})}}
    $text=Get-Content -Raw -LiteralPath $path;$edges=[ordered]@{};foreach($h in $headings){$id=$h.Id;$block=[regex]::Match($text,'(?ms)^## '+[regex]::Escape($id)+'\b.*?(?=^## |\z)').Value;$status=[regex]::Match($block,'(?m)^- \*\*Estado:\*\*\s*`?([a-z_]+)').Groups[1].Value;if($id -notin $Workflow.LegacyIds){if($status -notin @('proposed','accepted','rejected')){Trace-Fail 'ADR_METADATA_INVALID' $path $h.Line $id 'Estado no reconocido'};foreach($field in @('Decisor','Referencia de aprobación')){if($block -notmatch ('(?m)^- \*\*'+$field+':\*\*')){Trace-Fail 'ADR_METADATA_INVALID' $path $h.Line $id "falta $field"}}};$targets=[Collections.Generic.List[string]]::new();if($id -match '^(ADR-[0-9]{3,})-AMEND-[0-9]{3,}$'){$parent=$Matches[1];if(-not$seen.Contains($parent)){Trace-Fail 'ADR_AMENDMENT_INVALID' $path $h.Line $id "Parent ausente '$parent'"};$declaredParent=[regex]::Match($block,'(?m)^- \*\*Parent:\*\*\s*(ADR-[0-9]{3,})').Groups[1].Value;if(-not[string]::IsNullOrWhiteSpace($declaredParent)-and$declaredParent -cne $parent){Trace-Fail 'ADR_AMENDMENT_INVALID' $path $h.Line $id "Parent declarado '$declaredParent' no coincide con '$parent'"};[void]$targets.Add($parent)};foreach($rel in [regex]::Matches($block,'(?m)^- \*\*(?:Amends|Supersedes):\*\*\s*(ADR-[0-9]{3,})')){$target=$rel.Groups[1].Value;if($target -eq $id -or -not$seen.Contains($target)){Trace-Fail 'ADR_AMENDMENT_INVALID' $path $h.Line $id 'relación ADR inválida'};[void]$targets.Add($target)};if($targets.Count -gt 1){Trace-Fail 'ADR_AMENDMENT_INVALID' $path $h.Line $id 'una definición no puede declarar varias relaciones de enmienda'};$edges[$id]=@($targets)}
    foreach($start in $edges.Keys){$visited=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$cursor=$start;while($edges.Contains($cursor)-and@($edges[$cursor]).Count -gt 0){if(-not$visited.Add($cursor)){Trace-Fail 'ADR_AMENDMENT_INVALID' $path 0 $start 'ciclo de relaciones ADR'};$cursor=@($edges[$cursor])[0]}}
}
function Validate-TraceEvidenceStrict([string]$Root,[string]$Active,[string]$Phase) {
    $path=Join-Path $Root "specs/features/$Active/evidence.md";$lines=Read-TraceLines $path;$section='';$runSeen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$testSummary=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$acSummary=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach($item in $lines){$s=$item.Text;if($s -eq '## Ejecuciones automatizadas'){$section='run'}elseif($s -eq '## Verificaciones manuales'){$section='man'}elseif($s -eq '## Resumen final de pruebas'){$section='tests'}elseif($s -eq '## Resumen final de aceptación'){$section='acs'}elseif($s -match '^## '){$section=''};if($section -in @('run','man') -and $s -match '^\| (RUN|MAN)-[0-9]{3,} \|'){$c=Trace-Cells $s $path $item.Line 11;$id=$c[0];if(-not$runSeen.Add($id)){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $path $item.Line $id 'ejecución repetida'};foreach($index in @(2,3,4,5,9,10)){if([string]::IsNullOrWhiteSpace($c[$index])){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $path $item.Line $id 'campo obligatorio vacío'}};if($c[6] -eq 'pass' -and ($c[7] -cne '0' -or $c[8] -cne 'No aplica')){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $path $item.Line $id 'matriz pass inválida'};if($c[6] -in @('fail','blocked') -and $c[7] -eq '0'){Trace-Fail 'EVIDENCE_EXECUTION_INVALID' $path $item.Line $id 'matriz fail/blocked inválida'}};if($section -eq 'tests' -and $s -match '^\| (TEST-[0-9]{3,}) \|'){$id=$Matches[1];if(-not$testSummary.Add($id)){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' $path $item.Line $id 'TEST repetido'}};if($section -eq 'acs' -and $s -match '^\| (AC-[0-9]{3,}) \|'){$id=$Matches[1];if(-not$acSummary.Add($id)){Trace-Fail 'EVIDENCE_SUMMARY_INVALID' $path $item.Line $id 'AC repetida'}}}
}
$script:Inc05BaseInvokeTrace=${function:Invoke-TraceValidation}
function Invoke-TraceValidation([string]$Root,$Workflow,$Result){$r=& $script:Inc05BaseInvokeTrace $Root $Workflow $Result;Validate-TraceEvidenceStrict $Root $Result.Active $Result.Phase;return $r}
$script:Inc05BaseTransitionWithCR=${function:Transition}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){$change=$ChangeRequest;if($Destination -in @('spec_review','approved') -and -not[string]::IsNullOrWhiteSpace($change)){ $workflow=Read-Workflow $Root;$baseline=& $script:Inc05BaseValidateState $Root $workflow $false;Validate-ChangeRequest $Root $baseline.Active $change $ReferenceValue $baseline.Phase $Destination|Out-Null;& $script:Inc05BaseTransition $Root $Destination $ActorValue $ReferenceValue;return };& $script:Inc05BaseTransitionWithCR $Root $Destination $ActorValue $ReferenceValue}
$script:Inc05BaseInvokeTraceStrict=${function:Invoke-TraceValidation}
function Invoke-TraceValidation([string]$Root,$Workflow,$Result){$r=& $script:Inc05BaseInvokeTrace $Root $Workflow $Result;if($Result.Phase -in @('spec_review','approved','implementation','verification','publication_review','done') -and (Test-Path -LiteralPath (Join-Path $Root "specs/features/$($Result.Active)/evidence.md") -PathType Leaf)){Validate-TraceEvidenceStrict $Root $Result.Active $Result.Phase};return $r}
$script:Inc05TransitionWithDigest=${function:Transition}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){if($Destination -in @('specification','spec_review','approved') -and -not[string]::IsNullOrWhiteSpace($ChangeRequest)){$active=[string](Read-Yaml (Join-Path $Root 'progress/current.yaml')).active_feature;$crPath=Join-Path $Root "specs/features/$active/change-requests/$ChangeRequest.md";if(Test-Path -LiteralPath $crPath -PathType Leaf){$crText=Get-Content -Raw $crPath;$source=([regex]::Match($crText,'(?m)^- Digest de origen:\s*([^\r\n]+)$')).Groups[1].Value.Trim();if($source -ne (Get-Bundle $Root $active).Digest){Trace-Fail 'CHANGE_REQUEST_INVALID' $crPath 0 $ChangeRequest 'Digest de origen no coincide con bundle vigente'};if($Destination -in @('spec_review','approved')){$target=([regex]::Match($crText,'(?m)^- Digest objetivo:\s*([^\r\n]+)$')).Groups[1].Value.Trim();if($target -notmatch '^[0-9a-f]{64}$'){Trace-Fail 'CHANGE_REQUEST_INVALID' $crPath 0 $ChangeRequest 'Digest objetivo debe ser SHA-256 candidato'}}}};& $script:Inc05TransitionWithDigest $Root $Destination $ActorValue $ReferenceValue}
$script:Inc05ValidateChangeRequestOld=${function:Validate-ChangeRequest}
function Get-CrField([string]$Text,[string]$Name,[string]$Path,[string]$ChangeId) {
    $match=[regex]::Match($Text,'(?m)^- '+[regex]::Escape($Name)+':\s*([^\r\n]+)\r?$')
    if(-not $match.Success -or [string]::IsNullOrWhiteSpace($match.Groups[1].Value)){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId "falta campo '$Name'"}
    return $match.Groups[1].Value.Trim()
}
function Assert-CrTable([string]$Text,[string]$Heading,[string]$Header,[string]$Path,[string]$ChangeId) {
    $headingMatches=[regex]::Matches($Text,'(?m)^'+[regex]::Escape($Heading)+'\s*$');if($headingMatches.Count -ne 1){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId "tabla '$Heading' debe aparecer exactamente una vez"}
    $headingIndex=$headingMatches[0].Index;$tail=$Text.Substring($headingIndex+$headingMatches[0].Length);$nextHeading=[regex]::Match($tail,'(?m)^##\s+').Index;if($nextHeading -gt 0){$tail=$tail.Substring(0,$nextHeading)}
    $rows=@($tail -split "`r?`n"|Where-Object{-not[string]::IsNullOrWhiteSpace($_)});if($rows.Count -lt 2 -or $rows[0].Trim() -cne $Header -or $rows[1].Trim() -notmatch '^\|(?:---\|)+\s*$'){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId "tabla '$Heading' requiere cabecera y separador exactos"};$data=@($rows|Select-Object -Skip 2|Where-Object{$_.Trim().StartsWith('|')});if($data.Count -eq 0){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId "tabla '$Heading' sin filas"};foreach($row in $data){$trimmed=$row.Trim();if(($trimmed -split '\|').Count -ne (($Header.Trim() -split '\|').Count)){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId "fila inválida en '$Heading'"};if($trimmed -match '\|\s*\|'){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId "celda vacía en '$Heading'"};if($Heading -eq '## IDs afectados' -and $trimmed -notmatch '^\|\s*[^|]+\s*\|\s*(added|changed|removed)\s*\|\s*$'){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId 'Acción inválida en IDs afectados'};if($Heading -eq '## Cambio contractual' -and $trimmed -notmatch '^\|\s*[^|]+\s*\|\s*[^|]+\s*\|\s*$'){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId 'fila inválida en Cambio contractual'}}
}
function Assert-CrTopology([string]$Text,[string]$Path,[string]$ChangeId) {
    $expectedFields=@('ID','Feature','Estado','Digest de origen','Digest objetivo','Autor','Creada en','Motivo','Trabajo detenido','Impacto arquitectónico','Impacto de publicación','Decidido por','Decidido en','Referencia de decisión','Aprobaciones a renovar');$body=$Text.Substring(0,[Math]::Max(0,$Text.IndexOf('## ',[StringComparison]::Ordinal)));$actual=@([regex]::Matches($body,'(?m)^- ([^:]+):\s*[^\r\n]+\r?$')|ForEach-Object{$_.Groups[1].Value.Trim()});if($actual.Count -ne $expectedFields.Count -or (Compare-Object $expectedFields $actual -SyncWindow 0)){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId 'lista de campos o su orden no coincide con la topología canónica'};$expectedHeadings=@('## Cambio contractual','## IDs afectados','## Impactos','## Renovaciones');$actualHeadings=@([regex]::Matches($Text,'(?m)^##\s+[^\r\n]+\r?$')|ForEach-Object{$_.Value.Trim()});if($actualHeadings.Count -ne $expectedHeadings.Count -or (Compare-Object $expectedHeadings $actualHeadings -SyncWindow 0)){Trace-Fail 'CHANGE_REQUEST_INVALID' $Path 0 $ChangeId 'headings de CR ausentes, duplicadas o fuera de orden'}
}
function Validate-ChangeRequest([string]$Root,$Active,[string]$ChangeId,[string]$ReferenceValue,[string]$From,[string]$To,[string]$ExpectedOrigin) {
    $expected="specs/features/$Active/change-requests/$ChangeId.md"
    if($ReferenceValue -cne $expected){Trace-Fail 'CHANGE_REQUEST_INVALID' 'transition' 0 $ChangeId "-Reference debe ser '$expected'"}
    if($ChangeId -notmatch '^CR-[0-9]{3,}$'){Trace-Fail 'CHANGE_REQUEST_INVALID' 'transition' 0 $ChangeId 'ID de CR inválido'}
    $path=Join-Path $Root $expected
    if(-not(Test-Path -LiteralPath $path -PathType Leaf)){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'CR ausente'}
    $text=Read-BoundedUtf8 $path
    Assert-CrTopology $text $expected $ChangeId
    if(([regex]::Matches($text,'(?m)^# Change request —\s*([^\r\n]+)\s*$')).Count -ne 1 -or $text -notmatch ('(?m)^# Change request — '+[regex]::Escape($ChangeId)+'\s*$')){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 1 $ChangeId 'heading/ID no coinciden'}
    $values=@{}
    foreach($field in @('ID','Feature','Estado','Digest de origen','Digest objetivo','Autor','Creada en','Motivo','Trabajo detenido','Impacto arquitectónico','Impacto de publicación','Decidido por','Decidido en','Referencia de decisión','Aprobaciones a renovar')){$values[$field]=Get-CrField $text $field $expected $ChangeId}
    if($values['ID'] -cne $ChangeId -or $values['Feature'] -cne $Active){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'ID o Feature no coinciden con la transición'}
    foreach($dateField in @('Creada en','Decidido en')){if($values[$dateField] -cne 'pending'){try{Assert-Rfc3339 $values[$dateField] "$expected.$dateField"|Out-Null}catch{Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId "fecha inválida en '$dateField'"}}}
    foreach($impact in @('Impacto arquitectónico','Impacto de publicación')){if($values[$impact] -notin @('yes','no')){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId "impacto inválido en '$impact'"}}
    $bundle=(Get-Bundle $Root $Active).Digest
    $origin=$bundle;if(-not[string]::IsNullOrWhiteSpace($ExpectedOrigin)){$origin=$ExpectedOrigin};if($values['Digest de origen'] -notmatch '^[0-9a-f]{64}$' -or $values['Digest de origen'] -cne $origin){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'Digest de origen no coincide con el baseline del ciclo'}
    if($To -eq 'specification' -and ($From -notin @('approved','implementation','verification','publication_review') -or $values['Estado'] -cne 'approved_for_return' -or $values['Digest objetivo'] -cne 'pending')){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'retorno requiere arista gobernada, approved_for_return y Digest objetivo pending'}
    if($To -in @('spec_review','approved') -and $values['Digest objetivo'] -cne $bundle){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'Digest objetivo no coincide con el bundle candidato vigente'}
    if($To -eq 'spec_review' -and ($From -cne 'specification' -or $values['Estado'] -cne 'under_review' -or $values['Digest objetivo'] -notmatch '^[0-9a-f]{64}$')){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'spec_review requiere specification, under_review y digest candidato'}
    if($To -eq 'approved' -and ($From -cne 'spec_review' -or $values['Estado'] -cne 'closed' -or $values['Digest objetivo'] -notmatch '^[0-9a-f]{64}$')){Trace-Fail 'CHANGE_APPROVAL_STALE' $expected 0 $ChangeId 'approved requiere spec_review, CR closed y digest candidato'}
    Assert-CrTable $text '## Cambio contractual' '| Antes | Después |' $expected $ChangeId
    Assert-CrTable $text '## IDs afectados' '| ID | Acción |' $expected $ChangeId
    Assert-CrTable $text '## Impactos' '| Área | Impacto |' $expected $ChangeId
    Assert-CrTable $text '## Renovaciones' '| Puerta | Estado | Aprobado por | Aprobado en | Referencia | Digest |' $expected $ChangeId
    $renewalText=$text.Substring($text.IndexOf('## Renovaciones',[StringComparison]::Ordinal));$renewalRows=@([regex]::Matches($renewalText,'(?m)^\| (approvals\.[^|]+) \| ([^|]+) \| ([^|]+) \| ([^|]+) \| ([^|]+) \| ([^|]+) \|\s*$'));$listed=@($values['Aprobaciones a renovar'] -split ',\s*'|Where-Object{$_});$doors=@($renewalRows|ForEach-Object{$_.Groups[1].Value.Trim()});$canonical=@('approvals.specification','approvals.architecture','approvals.publication');if($listed.Count -eq 0 -or $listed.Count -ne $doors.Count){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'Aprobaciones a renovar y filas no coinciden'};for($i=0;$i -lt $listed.Count;$i++){if($listed[$i] -cne $doors[$i] -or $listed[$i] -notin $canonical -or ($i -gt 0 -and [array]::IndexOf($canonical,$listed[$i]) -le [array]::IndexOf($canonical,$listed[$i-1]))){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'Aprobaciones a renovar no están en orden canónico'} }
    $progress=Read-Yaml (Join-Path $Root 'progress/current.yaml');$decidedAt=if($values['Decidido en'] -ne 'pending'){Assert-Rfc3339 $values['Decidido en'] "$expected.Decidido en"}else{$null};foreach($row in $renewalRows){$gate=$row.Groups[1].Value.Trim();$stateValue=$row.Groups[2].Value.Trim();$approvedBy=$row.Groups[3].Value.Trim();$approvedAt=$row.Groups[4].Value.Trim();$renewalReference=$row.Groups[5].Value.Trim();$renewalDigest=$row.Groups[6].Value.Trim();if($To -eq 'approved'){if($stateValue -cne 'approved' -or [string]::IsNullOrWhiteSpace($approvedBy) -or [string]::IsNullOrWhiteSpace($renewalReference) -or $renewalDigest -cne $bundle){Trace-Fail 'CHANGE_APPROVAL_STALE' $expected 0 $ChangeId "renovación inválida para $gate"};try{$approvedDate=Assert-Rfc3339 $approvedAt "$expected.renovacion"}catch{Trace-Fail 'CHANGE_APPROVAL_STALE' $expected 0 $ChangeId 'fecha de renovación inválida'};if($null -ne $decidedAt -and $approvedDate -le $decidedAt){Trace-Fail 'CHANGE_APPROVAL_STALE' $expected 0 $ChangeId 'fecha de renovación debe ser posterior a Decidido en'};$gateName=$gate.Substring('approvals.'.Length);$approval=Require-Map (Require-Field (Require-Map $progress.approvals "$Root\progress\current.yaml.approvals") $gateName "$Root\progress\current.yaml.approvals") "$Root\progress\current.yaml.approvals.$gateName";if((Require-Text $approval.status "$Root\progress\current.yaml.approvals.$gateName.status") -cne 'approved' -or (Require-Text $approval.approved_by "$Root\progress\current.yaml.approvals.$gateName.approved_by") -cne $approvedBy -or (Require-Text $approval.reference "$Root\progress\current.yaml.approvals.$gateName.reference") -cne $renewalReference){Trace-Fail 'CHANGE_APPROVAL_STALE' $expected 0 $ChangeId "renovación $gate no coincide con progress"}}else{if($stateValue -cne 'pending' -or $approvedBy -cne 'pending' -or $approvedAt -cne 'pending' -or $renewalReference -cne 'pending' -or $renewalDigest -cne 'pending'){Trace-Fail 'CHANGE_REQUEST_INVALID' $expected 0 $ChangeId 'renovación no aprobada debe conservar pending en sus cinco celdas'}}}
    if($To -eq 'approved'){$specApproval=Require-Map $progress.approvals.specification "$Root\progress\current.yaml.approvals.specification";$review=Require-Map (Require-Field $specApproval 'review' "$Root\progress\current.yaml.approvals.specification") "$Root\progress\current.yaml.approvals.specification.review";if((Require-Text $review.status "$Root\progress\current.yaml.approvals.specification.review.status") -cne 'pass' -or (Require-Text $review.specification_digest "$Root\progress\current.yaml.approvals.specification.review.specification_digest") -cne $bundle -or (Require-Text $review.reviewed_by "$Root\progress\current.yaml.approvals.specification.review.reviewed_by") -eq (Require-Text $specApproval.approved_by "$Root\progress\current.yaml.approvals.specification.approved_by")){Trace-Fail 'CHANGE_APPROVAL_STALE' $expected 0 $ChangeId 'revisión independiente ausente, obsoleta o no independiente'}}
    $requestFiles=@(Get-ChildItem -LiteralPath (Join-Path $Root "specs/features/$Active/change-requests") -Filter 'CR-*.md' -File -ErrorAction SilentlyContinue)
    foreach($file in $requestFiles){$other=Read-BoundedUtf8 $file.FullName;$otherId=([regex]::Match($other,'(?m)^- ID:\s*([^\r\n]+)\r?$')).Groups[1].Value.Trim();$otherState=([regex]::Match($other,'(?m)^- Estado:\s*([^\r\n]+)\r?$')).Groups[1].Value.Trim();if($otherId -cne $ChangeId -and $otherState -in @('approved_for_return','under_review')){Trace-Fail 'CHANGE_REQUEST_CONFLICT' $file.FullName 0 $otherId 'existe otra CR no terminal'}}
    return $path
}
$script:Inc06BaseTransition=${function:Transition}
function Clear-ProgressBlockers([string]$Text) {
    $new=[regex]::Replace($Text,'(?ms)^blockers:\s*.*?(?=^risks:)',"blockers: []`n",1)
    if($new -eq $Text){Fail 'progress/current.yaml: no se pudo limpiar blockers'}
    return $new
}
function Resume-Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue) {
    if(-not [string]::IsNullOrWhiteSpace($ChangeRequest)-or-not [string]::IsNullOrWhiteSpace($BlockerCode)-or-not [string]::IsNullOrWhiteSpace($BlockerExplanation)-or@($BlockerReference).Count -gt 0){Trace-Fail 'RESUME_ARGUMENT_UNEXPECTED' 'transition' 0 'resume' 'reanudar no admite CR ni argumentos Blocker*'}
    Assert-NoRecovery $Root $false
    $workflow=Read-Workflow $Root
    $baseline=& $script:Inc05BaseValidateState $Root $workflow $false
    if($baseline.Phase -ne 'blocked'){return & $script:Inc06BaseTransition $Root $Destination $ActorValue $ReferenceValue}
    Validate-Blockers $Root $workflow $baseline
    $featureEvents=@($baseline.History.Events|Where-Object{$_.kind -eq 'transition' -and $_.feature -eq $baseline.Active})
    $last=if($featureEvents.Count -gt 0){$featureEvents[$featureEvents.Count-1]}else{$null}
    if($null -eq $last -or [string]$last.to -cne 'blocked' -or [string]::IsNullOrWhiteSpace([string]$last.from) -or [string]$last.from -eq 'blocked'){Trace-Fail 'RESUME_STATE_INVALID' 'progress/history.yaml' 0 'blocked' 'el último evento de la feature no es una entrada coherente a blocked'}
    $origin=[string]$last.from
    if(-not $workflow.StateSet.Contains($Destination)-or $Destination -eq 'blocked' -or -not(Has-Key $workflow.Transitions 'blocked') -or $Destination -notin @(Text-List $workflow.Transitions['blocked'] "$($workflow.Path).transitions.blocked")){Trace-Fail 'RESUME_TARGET_INVALID' 'transition' 0 $Destination 'destino no declarado para reanudación'}
    if($Destination -cne $origin){Trace-Fail 'RESUME_TARGET_INVALID' 'transition' 0 $Destination "reanudar solo permite el origen '$origin' del último blocked"}
    if($Destination-in$workflow.SpecIn-and-not(Test-ApprovalForTransition $baseline.Progress 'specification' $Root $baseline.Active)){if($workflow.ApprovalMode-eq'ask'){Trace-Fail 'APPROVAL_REQUEST' 'transition' 0 $Destination 'approval de specification ausente o inválida'}else{Trace-Fail 'APPROVAL_PROHIBITED' 'transition' 0 $Destination 'approval de specification ausente o inválida'}}
    if($Destination-in$workflow.PubIn-and-not(Test-ApprovalForTransition $baseline.Progress 'publication' $Root $baseline.Active)){if($workflow.ApprovalMode-eq'ask'){Trace-Fail 'APPROVAL_REQUEST' 'transition' 0 $Destination 'approval de publication ausente o inválida'}else{Trace-Fail 'APPROVAL_PROHIBITED' 'transition' 0 $Destination 'approval de publication ausente o inválida'}}
    if($Destination-in@('verification','publication_review','done')){$q=$baseline.Progress.quality;if(-not(Is-MapObject $q)-or[string]$q.status -ne 'pass'){Trace-Fail 'QUALITY_REQUIRED' 'progress/current.yaml' 0 'quality' 'quality.status debe ser pass antes de reanudar'};if((Require-Text $q.specification_digest "$($Root)\progress\quality.specification_digest")-ne(Get-Bundle $Root $baseline.Active).Digest){Trace-Fail 'QUALITY_STALE' 'progress/current.yaml' 0 'quality' 'quality no refiere el bundle vigente'}}
    $occurred=[DateTimeOffset]::Now.ToString('O',[Globalization.CultureInfo]::InvariantCulture);$max=0;foreach($e in $baseline.History.Events){if($e.id-match'^(?:TRN|MIG)-([0-9]+)$'){$n=[int]$Matches[1];if($n -gt $max){$max=$n}}};$id='TRN-'+($max+1).ToString('000');$gates=@();if($Destination-in$workflow.SpecIn){$gates+='approvals.specification'};if($Destination-in$workflow.PubIn){$gates+='approvals.publication'};if($workflow.ArchEnabled-and$Destination-in$workflow.ArchIn){$gates+='approvals.architecture'}
    $historyPath=Join-Path $Root 'progress/history.yaml';$featuresPath=Join-Path $Root 'features.yaml';$progressPath=Join-Path $Root 'progress/current.yaml';$paths=@($historyPath,$featuresPath,$progressPath);$before=@{};$after=@{};foreach($p in $paths){$before[$p]=[IO.File]::ReadAllBytes($p)};$after[$historyPath]=[Text.UTF8Encoding]::new($false).GetBytes((Append-Transition ([IO.File]::ReadAllText($historyPath)) $id $baseline.Active 'blocked' $Destination $occurred $ActorValue $ReferenceValue $gates));$after[$featuresPath]=[Text.UTF8Encoding]::new($false).GetBytes((Replace-ActiveStatus ([IO.File]::ReadAllText($featuresPath)) $baseline.Active $Destination));$after[$progressPath]=[Text.UTF8Encoding]::new($false).GetBytes((Replace-Phase (Clear-ProgressBlockers ([IO.File]::ReadAllText($progressPath))) $Destination));$stage=Get-StagingPath $Root;$journal=Get-JournalPath $Root;New-Item -ItemType Directory -Path $stage -Force|Out-Null
    try{$targets=[Collections.Generic.List[object]]::new();foreach($p in $paths){$name=[IO.Path]::GetFileName($p);Write-Bytes (Join-Path $stage "$name.before") $before[$p];Write-Bytes (Join-Path $stage "$name.after") $after[$p];$h=Get-Hash $p;if((Get-Hash (Join-Path $stage "$name.before")) -cne $h){Fail "staging before inconsistente para $name"};[void]$targets.Add([ordered]@{path=(Get-RelativePath $Root $p).Replace('\','/');before_sha256=$h;after_sha256=Get-Hash (Join-Path $stage "$name.after")})};$journalText="schema: 1`ncreated_at: $(Quote-Yaml $occurred)`nroot: '.'`nevent:`n  id: $id`n  feature: $(Quote-Yaml $baseline.Active)`n  from: 'blocked'`n  to: $(Quote-Yaml $Destination)`ntargets:`n";foreach($t in $targets){$journalText+="  - path: $(Quote-Yaml $t.path)`n    before_sha256: $(Quote-Yaml $t.before_sha256)`n    after_sha256: $(Quote-Yaml $t.after_sha256)`n"};Write-Bytes $journal ([Text.UTF8Encoding]::new($false).GetBytes($journalText));foreach($p in $paths){$name=[IO.Path]::GetFileName($p);Copy-Item -LiteralPath (Join-Path $stage "$name.after") -Destination $p -Force};$check=& $script:Inc05BaseValidateState $Root $workflow $true;if($check.Phase -ne $Destination){Fail 'validación interna: destino de reanudación no aplicado'};Remove-Item -LiteralPath $stage -Recurse -Force;Remove-Item -LiteralPath $journal -Force;Write-Host "TRANSITIONED: blocked → $Destination ($id)"}catch{throw}
}
$script:Inc05FinalTraceValidateState=${function:Validate-State}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){
    try{return (& $script:Inc05FinalTraceValidateState $Root $Workflow $SkipJournal)}catch{
        $message=$_.Exception.Message
        if($message -match "dependencia inexistente '([^']+)'"){Trace-Fail 'TRACE_FEATURE_MISSING' 'features.yaml' 0 $Matches[1] 'dependencia inexistente'}
        throw
    }
}
$script:Inc05ExplicitContractState=${function:Validate-State}
function Validate-State([string]$Root,$Workflow,[bool]$SkipJournal=$false){
    $result=& $script:Inc05ExplicitContractState $Root $Workflow $SkipJournal
    foreach($event in @($result.History.Events|Where-Object{$_.kind -eq 'transition'}) ){$from=[string]$event.from;$to=[string]$event.to;if(-not(Has-Key $Workflow.Transitions $from)-or$to-notin@(Text-List $Workflow.Transitions[$from] "$($Workflow.Path).transitions.$from")){Fail "progress/history.yaml.events[$($event.id)]: arista no declarada"}}
    if($result.Phase -in @('spec_review','approved','implementation','verification','publication_review','done') -and (Test-Path -LiteralPath (Join-Path $Root "specs/features/$($result.Active)/evidence.md") -PathType Leaf)){$contract=Parse-TraceContract $Root $result.Active;Validate-TraceRefs $contract $Root $result.Active;Validate-TraceEvidence $contract $Root $result.Active $result.Phase}
    return $result
}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){
    if($Destination -eq 'blocked'){return Transition-WithBlocker $Root $Destination $ActorValue $ReferenceValue $BlockerCode $BlockerExplanation $BlockerReference}
    if(-not [string]::IsNullOrWhiteSpace($BlockerCode)-or-not [string]::IsNullOrWhiteSpace($BlockerExplanation)-or @($BlockerReference).Count -gt 0){Trace-Fail 'BLOCKER_UNEXPECTED' 'transition' 0 'Blocker*' 'argumentos fuera de blocked'}
    $workflow=Read-Workflow $Root;$baseline=& $script:Inc05BaseValidateState $Root $workflow $false
    if($Destination -in @('specification','spec_review','approved')){
        $governedReturn=$Destination -eq 'specification' -and $baseline.Phase -in @('approved','implementation','verification','publication_review')
        if($Destination -ne 'specification' -or $governedReturn){
            if([string]::IsNullOrWhiteSpace($ChangeRequest)){Trace-Fail 'CHANGE_REQUEST_REQUIRED' 'transition' 0 'ChangeRequest' 'arista gobernada requiere CR'}
            Validate-ChangeRequest $Root $baseline.Active $ChangeRequest $ReferenceValue $baseline.Phase $Destination|Out-Null
        }elseif(-not [string]::IsNullOrWhiteSpace($ChangeRequest)){Trace-Fail 'CHANGE_REQUEST_UNEXPECTED' 'transition' 0 $ChangeRequest 'CR no aplica al avance inicial'}
        $last=@($baseline.History.Events|Where-Object{$_.kind -eq 'transition' -and $_.feature -eq $baseline.Active}|Select-Object -Last 1)
        if($Destination -eq 'spec_review' -and ($last.Count -eq 0 -or $last[0].to -ne 'specification' -or $last[0].reference -cne $ReferenceValue)){Trace-Fail 'CHANGE_REQUEST_INVALID' 'progress/history.yaml' 0 $ChangeRequest 'spec_review requiere el evento previo de specification con la misma referencia'}
        if($Destination -eq 'approved' -and ($last.Count -eq 0 -or $last[0].to -ne 'spec_review' -or $last[0].reference -cne $ReferenceValue)){Trace-Fail 'CHANGE_APPROVAL_STALE' 'progress/history.yaml' 0 $ChangeRequest 'approved requiere el evento previo de spec_review con la misma referencia'}
    }elseif(-not [string]::IsNullOrWhiteSpace($ChangeRequest)){Trace-Fail 'CHANGE_REQUEST_UNEXPECTED' 'transition' 0 $ChangeRequest 'CR no aplica a esta arista'}
    if($Destination -in @('verification','publication_review','done')){$prospective=[pscustomobject]@{Progress=$baseline.Progress;Features=$baseline.Features;History=$baseline.History;Active=$baseline.Active;Phase=$Destination};Invoke-TraceValidation $Root $workflow $prospective}
    & $script:Inc05BaseTransition $Root $Destination $ActorValue $ReferenceValue
}
function Get-OpenChangeContext([object]$History,[string]$Active) {
    $open=$null
    foreach($event in @($History.Events|Where-Object{$_.kind -eq 'transition' -and $_.feature -eq $Active})) {
        $from=[string]$event.from;$to=[string]$event.to;$reference=[string]$event.reference
        if($null -eq $open -and $to -eq 'specification' -and $from -in @('approved','implementation','verification','publication_review')) {
            if($reference -notmatch ('^specs/features/'+[regex]::Escape($Active)+'/change-requests/(CR-[0-9]{3,})\.md$')){Trace-Fail 'CHANGE_REQUEST_INVALID' 'progress/history.yaml' 0 $event.id 'retorno contractual sin referencia CR canónica'}
            $open=[pscustomobject]@{ChangeId=$Matches[1];Reference=$reference;OriginDigest=''}
        } elseif($null -ne $open -and $to -eq 'approved' -and $from -eq 'spec_review') {
            $open=$null
        }
    }
    return $open
}
function Get-ChangeOriginDigest([string]$Root,[string]$Active,[string]$ChangeId) {
    $path=Join-Path $Root "specs/features/$Active/change-requests/$ChangeId.md";if(-not(Test-Path -LiteralPath $path -PathType Leaf)){Trace-Fail 'CHANGE_REQUEST_INVALID' $path 0 $ChangeId 'CR ausente'}
    $value=([regex]::Match((Get-Content -Raw -LiteralPath $path),'(?m)^- Digest de origen:\s*([^\r\n]+)\r?$')).Groups[1].Value.Trim();if($value -notmatch '^[0-9a-f]{64}$'){Trace-Fail 'CHANGE_REQUEST_INVALID' $path 0 $ChangeId 'Digest de origen inválido'};return $value
}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){
    if($Destination -eq 'blocked'){return Transition-WithBlocker $Root $Destination $ActorValue $ReferenceValue $BlockerCode $BlockerExplanation $BlockerReference}
    if(-not [string]::IsNullOrWhiteSpace($BlockerCode)-or-not [string]::IsNullOrWhiteSpace($BlockerExplanation)-or @($BlockerReference).Count -gt 0){Trace-Fail 'BLOCKER_UNEXPECTED' 'transition' 0 'Blocker*' 'argumentos fuera de blocked'}
    $workflow=Read-Workflow $Root;$baseline=& $script:Inc05BaseValidateState $Root $workflow $false;$open=Get-OpenChangeContext $baseline.History $baseline.Active
    $hasChange=-not[string]::IsNullOrWhiteSpace($ChangeRequest)
    if($Destination -eq 'specification' -and $baseline.Phase -in @('approved','implementation','verification','publication_review')) {
        if($hasChange -eq $false){Trace-Fail 'CHANGE_REQUEST_REQUIRED' 'transition' 0 'ChangeRequest' 'retorno contractual requiere CR'}
        $currentOrigin=(Get-Bundle $Root $baseline.Active).Digest
        Validate-ChangeRequest $Root $baseline.Active $ChangeRequest $ReferenceValue $baseline.Phase $Destination $currentOrigin|Out-Null
    } elseif($Destination -in @('spec_review','approved') -and $null -ne $open) {
        if(-not $hasChange){Trace-Fail 'CHANGE_REQUEST_REQUIRED' 'transition' 0 'ChangeRequest' 'ciclo contractual abierto requiere CR'}
        if($ChangeRequest -cne $open.ChangeId -or $ReferenceValue -cne $open.Reference){Trace-Fail 'CHANGE_REQUEST_INVALID' 'progress/history.yaml' 0 $ChangeRequest 'CR o referencia no coinciden con el ciclo abierto'}
        $origin=[string]$open.OriginDigest
        Validate-ChangeRequest $Root $baseline.Active $ChangeRequest $ReferenceValue $baseline.Phase $Destination $origin|Out-Null
    } elseif($hasChange) {
        Trace-Fail 'CHANGE_REQUEST_UNEXPECTED' 'transition' 0 $ChangeRequest 'CR no aplica al recorrido inicial o a esta arista'
    }
    $last=@($baseline.History.Events|Where-Object{$_.kind -eq 'transition' -and $_.feature -eq $baseline.Active}|Select-Object -Last 1)
    if($Destination -eq 'spec_review' -and $null -eq $open -and ($last.Count -eq 0 -or $last[0].to -ne 'specification')){Trace-Fail 'CHANGE_REQUEST_INVALID' 'progress/history.yaml' 0 '' 'spec_review requiere specification previa'}
    if($Destination -eq 'approved' -and $null -eq $open -and ($last.Count -eq 0 -or $last[0].to -ne 'spec_review')){Trace-Fail 'CHANGE_APPROVAL_STALE' 'progress/history.yaml' 0 '' 'approved requiere spec_review previa'}
    if($Destination -in @('verification','publication_review','done')){$prospective=[pscustomobject]@{Progress=$baseline.Progress;Features=$baseline.Features;History=$baseline.History;Active=$baseline.Active;Phase=$Destination};Invoke-TraceValidation $Root $workflow $prospective}
    & $script:Inc05BaseTransition $Root $Destination $ActorValue $ReferenceValue
}
$script:Inc07BaseTextList=${function:Text-List}
function Text-List($Value,[string]$Path){$items=@(& $script:Inc07BaseTextList $Value $Path);if($Path -eq 'history.events[].gate_references'){$items=@($items|Where-Object{$_ -notmatch '^change-origin:[0-9a-f]{64}$'})};return $items}
$script:Inc07BaseOpenChangeContext=${function:Get-OpenChangeContext}
function Get-OpenChangeContext([object]$History,[string]$Active){$open=$null;foreach($event in @($History.Events|Where-Object{$_.kind -eq 'transition' -and $_.feature -eq $Active})){$from=[string]$event.from;$to=[string]$event.to;$reference=[string]$event.reference;$gates=@($event.gate_references);$originTokens=@($gates|Where-Object{$_ -match '^change-origin:[0-9a-f]{64}$'});if($null -eq $open -and $to -eq 'specification' -and $from -in @('approved','implementation','verification','publication_review')){if($reference -notmatch ('^specs/features/'+[regex]::Escape($Active)+'/change-requests/(CR-[0-9]{3,})\.md$')){Trace-Fail 'CHANGE_REQUEST_INVALID' 'progress/history.yaml' 0 $event.id 'retorno contractual sin referencia CR canónica'};if($originTokens.Count -ne 1){Trace-Fail 'CHANGE_REQUEST_INVALID' 'progress/history.yaml' 0 $event.id 'apertura contractual sin token change-origin único'};$changeId=([regex]::Match($reference,'(CR-[0-9]{3,})')).Groups[1].Value;$originDigest=$originTokens[0].Substring('change-origin:'.Length);$open=[pscustomobject]@{ChangeId=$changeId;Reference=$reference;OriginDigest=$originDigest}}elseif($null -ne $open -and $to -eq 'approved' -and $from -eq 'spec_review'){$open=$null}};return $open}
$script:Inc07BaseGetOpenChangeContext=${function:Get-OpenChangeContext}
function Get-OpenChangeContext([object]$History,[string]$Active){$result=& $script:Inc07BaseGetOpenChangeContext $History $Active;$script:OpenChangeOriginDigest=if($null -eq $result){''}else{[string]$result.OriginDigest};return $result}
$script:Inc07BaseGetChangeOriginDigest=${function:Get-ChangeOriginDigest}
function Get-ChangeOriginDigest([string]$Root,[string]$Active,[string]$ChangeId){if(-not[string]::IsNullOrWhiteSpace($script:OpenChangeOriginDigest)){return [string]$script:OpenChangeOriginDigest};& $script:Inc07BaseGetChangeOriginDigest $Root $Active $ChangeId}
$script:Inc07BaseTransition=${function:Transition}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){$origin=$null;if($Destination -eq 'specification' -and $ChangeRequest -and -not[string]::IsNullOrWhiteSpace($ChangeRequest)){$state=& $script:Inc05BaseValidateState $Root (Read-Workflow $Root) $false;if($state.Phase -in @('approved','implementation','verification','publication_review')){$origin=Get-ChangeOriginDigest $Root $state.Active $ChangeRequest}};$previous=$script:ChangeOriginDigestToPersist;try{$script:ChangeOriginDigestToPersist=$origin;& $script:Inc07BaseTransition $Root $Destination $ActorValue $ReferenceValue}finally{$script:ChangeOriginDigestToPersist=$previous}}
$script:Inc06DelegatedTransition=${function:Transition}
function Transition([string]$Root,[string]$Destination,[string]$ActorValue,[string]$ReferenceValue){
    $workflow=Read-Workflow $Root
    $state=& $script:Inc05BaseValidateState $Root $workflow $false
    if($state.Phase -eq 'blocked'){return Resume-Transition $Root $Destination $ActorValue $ReferenceValue}
    & $script:Inc06DelegatedTransition $Root $Destination $ActorValue $ReferenceValue
}
$script:Inc06StrictValidateADRs=${function:Validate-ADRs}
function Validate-ADRs([string]$Root,$Workflow){& $script:Inc06StrictValidateADRs $Root $Workflow}
$script:Inc05BaseValidateHarness=${function:Validate-Harness}
function Validate-Harness([string]$Root,[bool]$TemplateMode){
    & $script:Inc05BaseValidateHarness $Root $TemplateMode
    $workflow=Read-Workflow $Root;Validate-ADRs $Root $workflow;$state=& $script:Inc05BaseValidateState $Root $workflow $false
    if($state.Phase -in @('spec_review','approved','implementation','verification','publication_review','done') -and (Test-Path -LiteralPath (Join-Path $Root "specs/features/$($state.Active)/evidence.md") -PathType Leaf)){$contract=Parse-TraceContract $Root $state.Active;Validate-TraceRefs $contract $Root $state.Active;Validate-TraceEvidence $contract $Root $state.Active $state.Phase}
}
switch($Command){'validate'{$root=if([string]::IsNullOrWhiteSpace($Target)){$instanceRoot}else{FullPath $Target};Validate-Harness $root $Template.IsPresent};'version'{if($Template){Fail '-Template solo es válido con validate.'};Write-Output(Get-HarnessVersion $instanceRoot)};'init'{if($Template){Fail '-Template solo es válido con validate.'};$root=if([string]::IsNullOrWhiteSpace($Target)){$instanceRoot}else{FullPath $Target};Initialize-Project $root $ProjectName};'transition'{$root=if([string]::IsNullOrWhiteSpace($Target)){$instanceRoot}else{FullPath $Target};if(-not$Template){Check-Markers $root $false};Transition $root $To $Actor $Reference};'install'{Fail 'install se ejecuta desde el runtime del repositorio de desarrollo; use el wrapper scripts/harness.ps1.'}}
